parameters.jsCode:
// ===== État de la demande stocké dans le node "Request State Memory" =====
// (écrit par "Write State Memory", relu par "Read State Memory", clé = sessionId du chat)
const MEM_TAG = 'N8N_STATE_V8::';
function newRecord() { return { current: null, history: [], orders: [], updated_at: null }; }
function prevRecord() { const r = $('Load Request State').first().json.memory_record; return r && typeof r === 'object' ? JSON.parse(JSON.stringify(r)) : newRecord(); }
function toPayload(rec) { rec.updated_at = new Date().toISOString(); return MEM_TAG + JSON.stringify(rec); }
function specIdsOf(state) { return [...new Set((state?.functionalities || []).map(f => Array.isArray(f.candidate_offers) && f.candidate_offers[0] ? String(f.candidate_offers[0].spec_id || '') : '').filter(Boolean))].sort(); }
function obsTexts(json) { return (Array.isArray(json.intermediateSteps) ? json.intermediateSteps : []).map(s => { const o = s && s.observation; let t = typeof o === 'string' ? o : JSON.stringify(o ?? ''); try { const p = JSON.parse(t); if (typeof p === 'string') t = p; } catch (_) {} return t; }); }
// ================================================================================

// Texte de réponse Suivi + mise à jour de l'état réel des commandes connues pour "Write State Memory".
const j = $input.first().json;
let texte = j.output ?? '';
if (typeof texte === 'object' && texte !== null) texte = texte.reponse_utilisateur || texte.output || JSON.stringify(texte);
texte = String(texte).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/<\/?think>/gi, '').trim();
if (!texte) {
  let lang = 'fr';
  try { lang = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}
  texte = lang === 'en'
    ? "The status could not be presented. Check the TMF641/TMF638 call logs to verify the API response."
    : "Le suivi n'a pas pu être présenté. Consultez les journaux des appels TMF641/TMF638 pour vérifier la réponse des API.";
}

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const orderStates = {}, instStates = {};
for (const t of obsTexts(j)) {
  const d = new RegExp('Order ID:\\s*(' + UUID + ')[\\s\\S]*?State TMF641:\\s*([^\\n]+)', 'i').exec(t);
  if (d) { const ids = (/service_instance_ids:\s*([^\n]+)/i.exec(t) || [])[1]; orderStates[d[1]] = { state: d[2].trim(), sids: ids && !/none/i.test(ids) ? ids.split(',').map(s => s.trim()) : null }; }
  for (const m of t.matchAll(new RegExp('order_id=(' + UUID + ')\\s*\\|\\s*state=([^|\\n]+)(?:[^\\n]*service_instance_ids=([^|\\n]+))?', 'gi')))
    orderStates[m[1]] = { state: m[2].trim(), sids: m[3] && !/none/i.test(m[3]) ? m[3].split(',').map(s => s.trim()) : (orderStates[m[1]]?.sids ?? null) };
  for (const m of t.matchAll(/service_id=([^|\s]+)\s*\|\s*name=([^|]*)\|\s*state=([^|\n]+)/gi))
    instStates[m[1]] = { name: m[2].trim(), state: m[3].trim() };
}

let memory_payload = null;
const rec = prevRecord();
if (rec.orders.length && (Object.keys(orderStates).length || Object.keys(instStates).length)) {
  const now = new Date().toISOString(); let changed = false;
  for (const o of rec.orders) {
    const s = orderStates[o.order_id];
    if (s) { o.state = s.state; if (s.sids) o.service_instance_ids = s.sids; o.last_checked_at = now; changed = true; }
    const sids = Array.isArray(o.service_instance_ids) ? o.service_instance_ids : [];
    const inst = sids.filter(id => instStates[id]).map(id => ({ service_id: id, ...instStates[id] }));
    if (inst.length) { o.instances = inst; o.last_checked_at = now; changed = true; }
  }
  if (changed) memory_payload = toPayload(rec);
}
return [{ json: { output: texte, memory_payload } }];

// === LECTURE DES ARGUMENTS DE L'AGENT ===
// Dans un Code Tool, les arguments du LLM arrivent dans la variable `query`
// (objet si un Input Schema est defini, sinon chaine). $input contient l'item
// du workflow, PAS les arguments de l'outil -> ne jamais l'utiliser ici.
let params = {};
try {
  const q = (typeof query !== 'undefined') ? query : null;
  if (q && typeof q === 'object') {
    params = q;
  } else if (typeof q === 'string' && q.trim()) {
    const s = q.trim();
    try { params = JSON.parse(s); } catch (e) { params = { spec_id: s }; }
  }
} catch (e) { params = {}; }

if (typeof params !== 'object' || params === null) params = {};

let key = (params.spec_id || params.spec_name || params.name || '').toString().trim();
key = key.replace(/^["'\s]+|["'\s]+$/g, '');

if (!key) {
  return 'ARRET_OUTIL: aucun spec_id fourni. Ne rappelle PAS cet outil. '
       + 'Construis directement le JSON final a partir des resultats de RAG_Service_Offerings '
       + '(committed_sla = null si inconnu).';
}

const BASE = 'http://openslice.example';
const SPEC = '/tmf-api/serviceCatalogManagement/v4/serviceSpecification';

const tk = await this.helpers.httpRequest({
  method: 'POST',
  url: BASE + '/auth/realms/openslice/protocol/openid-connect/token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: 'grant_type=password&client_id=osapiWebClientId&username=__OPENSLICE_USERNAME__&password=__OPENSLICE_PASSWORD__',
  json: true,
});
const token = tk.access_token;
const H = { 'Authorization': 'Bearer ' + token };

const isUuid = s => /^[0-9a-f]{8}-[0-9a-f]{4}/i.test(s);
const getSpec = async id =>
  this.helpers.httpRequest({ method:'GET', url: BASE+SPEC+'/'+id, headers:H, json:true });

const readChars = spec => {
  const norm = {};
  const units = {};
  const pairs = [];
  for (const c of (spec.serviceSpecCharacteristic || [])) {
    if (!c || !c.name || c.name === 'SSPEC_GRAPH_NOTATION') continue;
    const v = (c.serviceSpecCharacteristicValue || [])[0];
    let val = v ? v.value : '';
    if (val && typeof val === 'object') val = (val.value !== undefined ? val.value : JSON.stringify(val));
    if (val === undefined || val === null) val = '';
    const unit = v && v.unitOfMeasure ? String(v.unitOfMeasure).trim() : '';
    norm[c.name.toLowerCase().trim()] = val;
    units[c.name.toLowerCase().trim()] = unit;
    pairs.push(c.name + '=' + val + (unit ? ' ' + unit : ''));
  }
  return { norm, units, pairs };
};

// Codes d'isolation du catalogue (GST) -> libellé
const ISO_LABELS = { '0':'No Isolation', '1':'Physical Isolation', '2':'Logical Isolation' };
const isoLabel = v => {
  const s = String(v ?? '').trim();
  if (!s) return s;
  if (/[a-z]/i.test(s)) return s;                                  // déjà un libellé
  return ISO_LABELS[s] ? `${ISO_LABELS[s]} (${s})` : `code ${s} (non répertorié)`;
};

const pickKey = (norm, subs) => {
  for (const s of subs) for (const k of Object.keys(norm)) if (k.includes(s)) return k;
  return null;
};
// Conversion en millisecondes à partir de unitOfMeasure (null si non convertible)
const toMs = (val, unit) => {
  const n = parseFloat(String(val ?? '').replace(',', '.'));
  if (!Number.isFinite(n)) return null;
  const u = String(unit || '').toLowerCase().replace(/[^a-zµμ]/g, '');
  if (['seconds','second','sec','s'].includes(u)) return +(n * 1000).toPrecision(12);
  if (['milliseconds','millisecond','msec','ms'].includes(u)) return n;
  if (['microseconds','microsecond','us','µs','μs'].includes(u)) return n / 1000;
  return null;
};
const pickFrom = (norm, subs) => {
  for (const k of Object.keys(norm)) {
    for (const s of subs) if (k.includes(s)) return norm[k];
  }
  return '';
};

let cfs;
if (isUuid(key)) {
  cfs = await getSpec(key);
} else {
  const list = await this.helpers.httpRequest({ method:'GET', url: BASE+SPEC, headers:H, qs:{limit:100}, json:true });
  let hit = (list || []).find(s => (s.name||'').toLowerCase() === key.toLowerCase())
         || (list || []).find(s => (s.name||'').toLowerCase().includes(key.toLowerCase()));
  if (hit && hit.id) cfs = await getSpec(hit.id);
}
if (!cfs || !cfs.id) return 'ARRET_OUTIL: aucune CFS trouvee pour "' + key + '". Ne rappelle PAS cet outil avec cette valeur. Passe au CFS suivant ou termine.';

const C = readChars(cfs);
const latKey = pickKey(C.norm, ['packet delay budget', 'latency']);
const latMs  = latKey ? toMs(C.norm[latKey], C.units[latKey]) : null;
const sla = {
  sST:         pickFrom(C.norm, ['snssai','sst']),
  latency_ms:  latMs !== null ? latMs : '',
  latency:     latMs === null && latKey ? (C.norm[latKey] + (C.units[latKey] ? ' ' + C.units[latKey] : '')) : '',
  availability: pickFrom(C.norm, ['availability']),
  isolation:   pickFrom(C.norm, ['isolation']),
  maxUEs:      pickFrom(C.norm, ['maximum number','number of ue','max ue','maxue','nb ue']),
  mobility:    pickFrom(C.norm, ['mobility']),
};

const rels = (cfs.serviceSpecRelationship || []).filter(r =>
  (r.relationshipType || '').toLowerCase().includes('realiz'));
let rfsBlocks = [];
for (const rel of rels) {
  try {
    const rfs = await getSpec(rel.id);
    const rc = readChars(rfs);
    rfsBlocks.push('  - ' + rfs.name + ': ' + rc.pairs.slice(0, 6).join(', '));
  } catch(e) { rfsBlocks.push('  - ' + (rel.name || rel.id)); }
}

let out = 'CFS: ' + cfs.name + '\nspec_id: ' + cfs.id + '\n';
out += 'COMMITTED_SLA: ' + Object.entries(sla)
  .filter(([k, v]) => v !== '' && v !== null && v !== undefined)
  .map(([k, v]) => k + '=' + String(k === 'isolation' ? isoLabel(v) : v).replace(/,/g, ';'))
  .join(', ') + '\n';
out += 'ALL_CFS_CHARACTERISTICS:\n  ' + (C.pairs.length ? C.pairs.join('\n  ') : '(none)') + '\n';
out += 'REALIZED_BY (RFS):\n' + (rfsBlocks.length ? rfsBlocks.join('\n') : '  (no RFS linked)');
return out;

