// ================= PARAMÈTRES DE PLANIFICATION (modifiables ici) =================
const ORDER_ITEM_STATE   = 'ACKNOWLEDGED'; // 'ACKNOWLEDGED' = fulfillment automatique, 'INITIAL' = validation manuelle
const START_DELAY_MIN    = 0;              // décalage du début par rapport à maintenant, en minutes
const DEFAULT_DURATION_H =24;              // durée par défaut avant décommissionnement auto ; 0 = pas de date de fin
// ================================================================================

// Arguments de l'agent = variable `query` (pas $input)
let params = {};
try {
  const q = (typeof query !== 'undefined') ? query : null;
  if (q && typeof q === 'object') params = q;
  else if (typeof q === 'string' && q.trim()) { try { params = JSON.parse(q); } catch (e) { params = {}; } }
} catch (e) { params = {}; }
if (typeof params !== 'object' || params === null) params = {};

// On accepte une LISTE de services -> UNE SEULE commande contenant plusieurs orderItem.
// Compatibilite : un spec_id seul est accepte et traite comme une liste d'un element.
let services = params.services || params.items || params.offers;
if (!Array.isArray(services)) {
  services = (params.spec_id) ? [{ spec_id: params.spec_id, spec_name: params.spec_name }] : [];
}

const clean = [];
const seen = new Set();
for (const s of services) {
  if (!s || typeof s !== 'object') continue;
  const id = String(s.spec_id || s.id || '').trim();
  const nm = String(s.spec_name || s.name || '').trim();
  if (id.length < 10) continue;          // UUID invalide -> ignore
  if (seen.has(id)) continue;            // dedoublonnage : jamais 2 fois la meme CFS
  seen.add(id);
  clean.push({ id, name: nm || id });
}

if (!clean.length) {
  return 'ARRET_OUTIL: aucun spec_id valide fourni. Ne rappelle PAS cet outil. '
       + 'Attendu : {"services":[{"spec_id":"<uuid>","spec_name":"<nom>"}, ...], "rationale":"...", "duration_hours":1}';
}

// ---- Fenêtre de service TMF641 : requestedStartDate = déploiement, requestedCompletionDate = teardown ----
const NOW = new Date();
const valid = d => d instanceof Date && !isNaN(d.getTime());
let start = params.requested_start_date ? new Date(params.requested_start_date) : null;
if (!valid(start)) start = new Date(NOW.getTime() + START_DELAY_MIN * 60000);

let hours = Number(params.duration_hours);
if (!Number.isFinite(hours) || hours < 0) hours = DEFAULT_DURATION_H;

let end = params.requested_completion_date ? new Date(params.requested_completion_date) : null;
if (!valid(end)) end = hours > 0 ? new Date(start.getTime() + hours * 3600000) : null;
// garde-fou : une date de fin déjà passée ferait décommissionner le service aussitôt après le déploiement
let endAdjusted = false;
if (end && end.getTime() < NOW.getTime() + 5 * 60000) {
  end = new Date(NOW.getTime() + (hours > 0 ? hours : DEFAULT_DURATION_H) * 3600000);
  endAdjusted = true;
}
const fr = d => d ? d.toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'short', timeStyle: 'short' }) : 'non définie';

const BASE = 'http://openslice.example';

const tokenResp = await this.helpers.httpRequest({
  method: 'POST',
  url: BASE + '/auth/realms/openslice/protocol/openid-connect/token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: 'grant_type=password&client_id=osapiWebClientId&username=__OPENSLICE_USERNAME__&password=__OPENSLICE_PASSWORD__',
  returnFullResponse: false,
  json: true,
});
const token = tokenResp.access_token;

// UNE ServiceOrder, N orderItem (un par service demande)
const orderBody = {
  "category": "Network Slice Order",
  "description": String(params.rationale || 'Commande groupee generee par l agent IA').substring(0, 250),
  "@type": "ServiceOrder",
  "requestedStartDate": start.toISOString(),
  "orderItem": clean.map((s, i) => ({
    "id": String(i + 1),
    "action": "add",
    "state": ORDER_ITEM_STATE,        // ACKNOWLEDGED => OpenSlice enchaine le deploiement sans action manuelle
    "@type": "ServiceOrderItem",
    "service": {
      "serviceSpecification": {
        "id": s.id,
        "name": s.name,
        "@type": "ServiceSpecificationRef"
      }
    }
  }))
};
if (end) orderBody.requestedCompletionDate = end.toISOString();

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: BASE + '/tmf-api/serviceOrdering/v4/serviceOrder',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify(orderBody),
    returnFullResponse: true,
  });

  if (resp.statusCode >= 200 && resp.statusCode < 300) {
    let result;
    try { result = JSON.parse(resp.body); } catch (e) { result = resp.body; }
    const orderId = result.id || result.uuid || 'inconnu';
    const state = result.state || 'soumis';
    const lignes = clean.map((s, i) => '  ' + (i + 1) + '. ' + s.name + ' (spec_id: ' + s.id + ')').join('\n');
    return 'UNE Service Order creee dans OpenSlice pour ' + clean.length + ' service(s).\n'
         + 'Order ID: ' + orderId + '\nStatut: ' + state + '\n'
         + 'Debut demande (requestedStartDate): ' + (result.requestedStartDate || orderBody.requestedStartDate) + ' (' + fr(start) + ' Paris)\n'
         + 'Fin demandee (requestedCompletionDate): ' + (end ? (result.requestedCompletionDate || orderBody.requestedCompletionDate) + ' (' + fr(end) + ' Paris)' : 'aucune, le service reste actif jusqu a demande de fin')
         + (end ? '\nDuree: ' + Math.round((end - start) / 36000) / 100 + ' h — le service sera decommissionne automatiquement a cette date.' : '')
         + (endAdjusted ? '\nATTENTION: la date de fin demandee etait passee, elle a ete recalculee.' : '')
         + '\nServices inclus :\n' + lignes;
  }
  return 'Erreur HTTP ' + resp.statusCode + ': '
       + (typeof resp.body === 'string' ? resp.body.substring(0, 300) : JSON.stringify(resp.body).substring(0, 300));
} catch (err) {
  return 'Erreur reseau: ' + err.message;
}

