const BASE = 'http://openslice.example';
const ORDER_PATH = '/tmf-api/serviceOrdering/v4/serviceOrder';
const tokenResp = await this.helpers.httpRequest({
  method:'POST', url:BASE+'/auth/realms/openslice/protocol/openid-connect/token',
  headers:{'Content-Type':'application/x-www-form-urlencoded'},
  body:'grant_type=password&client_id=osapiWebClientId&username=__OPENSLICE_USERNAME__&password=__OPENSLICE_PASSWORD__', json:true
});
const H = {'Authorization':'Bearer '+tokenResp.access_token};

function itemInfo(it) {
  const svc = (it && it.service) || {};
  const spec = svc.serviceSpecification || {};
  const supporting = Array.isArray(svc.supportingService) ? svc.supportingService : [];
  return {
    item_id: it?.id || '', action: it?.action || '', item_state: it?.state || '',
    spec_id: spec.id || '', spec_name: spec.name || '', service_id: svc.id || '',
