  if(a.length!==b.length) return false;
  for(let i=0;i<a.length;i++) if(a[i]!==b[i]) return false;
  return true;
}
function formatOrder(info) {
  const lines = info.items.map(x =>
    `  - item=${x.item_id||'N/A'} | state=${x.item_state||'N/A'} | CFS=${x.spec_name||'N/A'} | spec_id=${x.spec_id||'N/A'} | service_id=${x.service_id||'N/A'}`
    + (x.supporting_service_ids.length ? ` | supportingService_ids=${x.supporting_service_ids.join(',')}` : '')
  );
  return [
    `Order ID: ${info.order_id||'N/A'}`,
    `State TMF641: ${info.state||'N/A'}`,
    `Date: ${info.order_date||'N/A'}`,
    `spec_ids: ${info.spec_ids.length ? info.spec_ids.join(',') : '(none)'}`,
    `service_instance_ids: ${info.service_instance_ids.length ? info.service_instance_ids.join(',') : '(none)'}`,
    'Order items:', ...(lines.length ? lines : ['  (none)'])
  ].join('\n');
