if (looksLikeUuid) {
  try {
    const o = await this.helpers.httpRequest({method:'GET',url:BASE+ORDER_PATH+'/'+search,headers:H,json:true});
    return 'TMF641_SERVICE_ORDER\n'+formatOrder(orderInfo(o));
