  return `- service_id=${x.service_id||'N/A'} | name=${x.name||'N/A'} | state=${x.state||'N/A'} | category=${x.category||'N/A'} | spec=${x.spec_name||'N/A'} | spec_id=${x.spec_id||'N/A'} | start=${x.startDate||'N/A'} | end=${x.endDate||'N/A'}`;
