// ===== État de la demande lu depuis "Read State Memory" (Simple Memory, clé = sessionId) =====
const MEM_TAG = 'N8N_STATE_V8::';
const trigger = $('When chat message received').first().json;
const sessionId = String(trigger.sessionId || 'default');
const chatInput = String(trigger.chatInput || '').trim();

// ===== Détection de la langue de la demande (fr/en) — toute la conversation répond dans cette langue =====
// Basée sur un score de mots-clés complets (pas de sous-chaîne), donc insensible à la ponctuation
// ET insensible aux noms propres accentués (ex: "Île-de-France", "Côte d'Azur" dans un message anglais).
function detectLang(text) {
  const lower = String(text || '').toLowerCase().normalize('NFC');
  // \p{L}\p{M}' capture les lettres (incl. accentuées) et apostrophes ; unicode-aware via le flag u
  const words = lower.match(/[\p{L}\p{M}']+/gu) || [];

  const FR = new Set(['le','la','les','des','une','un','du','de','pour','avec','dans','est','sont','que','qui',
    'vous','nous','je','j\'ai','bonjour','merci','svp','s\'il','débit','besoin','caméra','caméras','région',
    'régions','faut','voudrais','souhaite','souhaitons','peut','pouvez','garanti','garantie','garantis',
    'garantissent','fixé','fixée','fixés','demande','notre','nos','votre','vos','ces','cette','ce','au','aux',
    'doit','doivent','être','avoir','sans','plusieurs','centre','traitement','flux','vidéo','vers','seul',
    'unique','service','chaque','affecté','affectée','indépendamment','réseau','charge','installées','installés']);
  const EN = new Set(['the','and','for','with','need','please','hello','hi','want','would','could','camera',
    'cameras','region','regions','rate','service','guarantee','guaranteed','order','status','thanks','fixed',
    'request','our','your','their','this','that','from','must','be','single','stream','streams','video',
    'processing','center','installed','assigned','regardless','network','load','like','subscribe','delivery',
    'each','ensure','continuous','without']);

  let frScore = 0, enScore = 0;
  for (const w of words) {
    if (FR.has(w)) frScore++;
    if (EN.has(w)) enScore++;
  }
  if (lower.includes('thank you')) enScore++;

  if (frScore === 0 && enScore === 0) return null; // ambigu (ex: juste des chiffres/noms propres)
  if (frScore === enScore) return null;             // égalité : indécidable, on laisse le défaut décider
  return frScore > enScore ? 'fr' : 'en';
}
const lang = detectLang(chatInput) || 'fr'; // défaut FR si vraiment ambigu

// Cherche le dernier message mémoire contenant l'état (format simplifié ou LangChain brut)
function findState(v, d = 0) {
  if (v == null || d > 12) return null;
  if (typeof v === 'string') { const i = v.lastIndexOf(MEM_TAG); if (i >= 0) { try { return JSON.parse(v.slice(i + MEM_TAG.length)); } catch (_) {} } return null; }
  if (Array.isArray(v)) { for (let k = v.length - 1; k >= 0; k--) { const r = findState(v[k], d + 1); if (r) return r; } return null; }
  if (typeof v === 'object') { for (const x of Object.values(v)) { const r = findState(x, d + 1); if (r) return r; } }
  return null;
}
let rec = null;
try { const its = $('Read State Memory').all(); for (let i = its.length - 1; i >= 0 && !rec; i--) rec = findState(its[i].json); } catch (e) { rec = null; }
if (!rec || typeof rec !== 'object') rec = { current: null, history: [], orders: [], updated_at: null };
if (!Array.isArray(rec.orders)) rec.orders = [];
if (!Array.isArray(rec.history)) rec.history = [];

const current = rec.current && typeof rec.current === 'object' ? rec.current : null;
const orders = rec.orders;
const last_order = orders.length ? orders[orders.length - 1] : null;

function summary(s) {
  if (!s || !Array.isArray(s.functionalities)) return 'AUCUNE_DEMANDE_ACTIVE';
  const lines = [`request_id=${s.request_id || 'N/A'} revision=${s.revision || 0}`];
  for (const f of s.functionalities) {
    const req = f.requirements && typeof f.requirements === 'object' ? JSON.stringify(f.requirements) : '{}';
    const cfs = Array.isArray(f.candidate_offers) && f.candidate_offers[0] ? (f.candidate_offers[0].spec_name || f.candidate_offers[0].name || '') : '';
    const sup = f.categorie === 'support' ? ` [support${(f.supports || []).length ? ' de ' + f.supports.join(',') : ''}]` : '';
    lines.push(`${f.id}${sup}: ${f.business_capability_name || 'N/A'} | ${f.sous_type_5g || 'N/A'} | requirements=${req}${cfs ? ` | CFS=${cfs}` : ''}`);
  }
  if (s.bundle_offer && s.bundle_offer.spec_id) lines.push(`BUNDLE: ${s.bundle_offer.spec_name || s.bundle_offer.spec_id} couvre ${(s.bundle_offer.covered_functionalities || []).join(',')}`);
  if (last_order) lines.push(`COMMANDE: order_id=${last_order.order_id} | state=${last_order.state || 'N/A'} | revision=${last_order.revision ?? 'N/A'}`);
  return lines.join('\n').slice(0, 5000);
}
return [{ json: {
  chatInput, sessionId, lang,
  has_state: !!current,
  current_state: current,
  state_summary: summary(current),
  orders, last_order,
  memory_record: rec,                                   // repris par les nodes qui mettent l'état à jour
  memory_payload_prev: MEM_TAG + JSON.stringify(rec),   // réécrit tel quel si rien n'a changé
  state_backend: 'simple_memory'
} }];

// =============================================================================
// Node "Decomposition Merge"                                     v3
// - décomposition : construit le portfolio (max 8 capacités, métier + support)
// - complément    : applique add/update/remove de façon déterministe sur l'état courant
// v3 : capacités SUPPORT (edge BC-009 / transport BC-010)
//   * déduites des capacités techniques TC-013..TC-016 (edge) et TC-017/TC-018 (transport)
//   * une TC edge/transport posée sur une capacité métier crée (ou complète) la capacité
//     support correspondante, liée par "supports"
//   * règles de prudence : une capacité support nouvelle exige un indice explicite
//     dans le message utilisateur (sinon elle est écartée et journalisée)
//   * suppression en cascade d'un support dont toutes les capacités servies ont été retirées
// =============================================================================
const MAX_FUNCS = 8;
const MAX_OPS = 8;

function clean(s){return String(s??'').replace(/<think>[\s\S]*?<\/think>/gi,'').replace(/<\/?think>/gi,'').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();}
function clone(v){return v===undefined?undefined:JSON.parse(JSON.stringify(v));}
function stable(v){if(Array.isArray(v))return '['+v.map(stable).join(',')+']';if(v&&typeof v==='object'){return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}';}return JSON.stringify(v);}
const uniq = a => [...new Set(a)];
function capKey(f){
  const base=[f.business_capability_id||'',...(Array.isArray(f.technical_capability_ids)?[...f.technical_capability_ids].sort():[])].filter(Boolean);
  if(f.categorie==='support')base.push('supports:'+[...(f.supports||[])].sort().join(','));
  return base.join(';');
}
function signature(f){return stable({description:f.description||'',categorie:f.categorie||'metier',supports:[...(f.supports||[])].sort(),bc:f.business_capability_id||null,bcn:f.business_capability_name||null,tc:Array.isArray(f.technical_capability_ids)?[...f.technical_capability_ids].sort():[],tcn:Array.isArray(f.technical_capability_names)?[...f.technical_capability_names].sort():[],slice:f.sous_type_5g||null,requirements:f.requirements||{}});}
function normalizeReq(f){if(!f.requirements||typeof f.requirements!=='object'||Array.isArray(f.requirements))f.requirements={};if(f.requirements.region&&!f.requirements.regions){f.requirements.regions=[String(f.requirements.region)];delete f.requirements.region;}if(f.requirements.regions&&!Array.isArray(f.requirements.regions))f.requirements.regions=[String(f.requirements.regions)];if(Array.isArray(f.requirements.regions))f.requirements.regions=[...new Set(f.requirements.regions.map(x=>String(x).trim()).filter(Boolean))];}
function initNew(f,id){f.id=id;normalizeShape(f);normalizeReq(f);applyAvailabilityTC(f);delete f.requirements_diff;f.matched_generic_service=null;f.recommandations_metier=null;f.candidate_offers=[];f.reused_context={matched_generic_service:null,recommandations_metier:null,candidate_offers:[]};f.idempotence={capability_key:capKey(f),capability_status:'new',generic_service_status:'unknown',business_recommendation_status:'unknown',offer_status:'unknown'};return f;}
function markUnchanged(f){normalizeReq(f);delete f.requirements_diff;if(!Array.isArray(f.candidate_offers))f.candidate_offers=[];if(!f.idempotence||typeof f.idempotence!=='object')f.idempotence={};f.idempotence.capability_key=capKey(f);f.idempotence.capability_status='existing_unchanged';f.idempotence.generic_service_status=f.matched_generic_service?'existing_reused':(['not_found','tool_error'].includes(String(f.idempotence.generic_service_status||''))?f.idempotence.generic_service_status:'not_found');f.idempotence.business_recommendation_status=f.recommandations_metier?'existing_reused':(['not_found','tool_error','not_applicable'].includes(String(f.idempotence.business_recommendation_status||''))?f.idempotence.business_recommendation_status:'not_applicable');f.idempotence.offer_status=f.candidate_offers.length===1?'existing_reused':(['not_found','tool_error','not_applicable'].includes(String(f.idempotence.offer_status||''))?f.idempotence.offer_status:'not_found');f.reused_context={matched_generic_service:clone(f.matched_generic_service??null),recommandations_metier:f.recommandations_metier??null,candidate_offers:clone(f.candidate_offers)};return f;}
function resetImpacted(f){normalizeReq(f);const previous={matched_generic_service:clone(f.matched_generic_service??null),recommandations_metier:f.recommandations_metier??null,candidate_offers:clone(Array.isArray(f.candidate_offers)?f.candidate_offers:[])};f.matched_generic_service=null;f.recommandations_metier=null;f.candidate_offers=[];f.reused_context=previous;if(!f.idempotence||typeof f.idempotence!=='object')f.idempotence={};f.idempotence.capability_key=capKey(f);f.idempotence.capability_status='existing_updated';f.idempotence.generic_service_status='unknown';f.idempotence.business_recommendation_status='unknown';f.idempotence.offer_status='unknown';return f;}

// --- v2 : capacités de disponibilité (seuils GST NG.116), affectées de façon déterministe ---
// Low <90 % · Medium 90-95 % · High >95-99.999 % · Very high >99.999 %
const AVAIL_TC={'TC-011':'HighAvailability','TC-012':'VeryHighAvailability'};
function applyAvailabilityTC(f){const ids=Array.isArray(f.technical_capability_ids)?f.technical_capability_ids:[];const names=Array.isArray(f.technical_capability_names)?f.technical_capability_names:[];const keep=ids.map((id,i)=>[id,names[i]]).filter(([id])=>!(id in AVAIL_TC));const a=f.requirements?.availability;const v=Number(a&&typeof a==='object'?a.value:a);if(a!==undefined&&a!==null&&Number.isFinite(v)){if(v>99.999)keep.push(['TC-012',AVAIL_TC['TC-012']]);else if(v>95)keep.push(['TC-011',AVAIL_TC['TC-011']]);}f.technical_capability_ids=keep.map(x=>x[0]);f.technical_capability_names=keep.map(x=>x[1]??null);}
// --- v2 : garde-fou remplacement / négation sur les régions (le LLM confond parfois remplacer et ajouter) ---
const nrmTxt=s=>' '+String(s??'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[’`]/g,"'").replace(/[^a-z0-9']+/g,' ').trim()+' ';
const REPLACE_CUE=/ (plutot|au lieu|remplac\w*|en fait|corrig\w*|non pas|pas a|pas en|pas sur|erreur|change\w*|modifi\w*|plus a|plus en|plus sur) /;
const ADD_CUE=/ (aussi|en plus|ajout\w*|egalement|supplementaire\w*|de plus|rajout\w*|etend\w*|extension) /;
function isNegated(msg,val){msg=msg.replace(/ (en|de) plus (d'|de |des |du )?/g,' ');const x=nrmTxt(val).trim().replace(/[.*+?^${}()|[\]\\]/g,'\\$&');if(!x)return false;return new RegExp(" (pas|non|plus|sauf|hors|retire\\w*|enleve\\w*|supprime\\w*|remplace\\w*|au lieu d'?e?|plutot que|plutot qu') (a |de |la |le |l'|d')?(region |zone |ville |site )?"+x+" ").test(msg);}

// =============================================================================
// v3 : CAPACITÉS SUPPORT (edge / transport)
// =============================================================================
const SUPPORT = {
  edge: { bc:'BC-009', bcn:'EdgeComputing',
          tcs:{ 'TC-013':'LocalProcessing', 'TC-014':'ComputeOffload', 'TC-015':'LocalBreakout', 'TC-016':'LocalTraffic' },
          req:['compute','storage','edge_location'],
          // indices explicites exigés dans le message pour CRÉER une capacité edge (règle de prudence)
          cue:/ (edge|mec|proximit\w*|proximity|near the (site|devices)|multi ?access|bord du reseau|peripherie du reseau|sur site|on ?prem\w*|in situ|local\w*|traitement\w*|calcul\w*|compute|inference\w*|analyse\w*|analytics|ia|intelligence artificielle|offload\w*|deport\w*|breakout|gpu|cpu|vcpu|serveur\w*|processing|on site) / },
  transport: { bc:'BC-010', bcn:'TransportConnectivity',
          tcs:{ 'TC-017':'SiteToSiteTransport', 'TC-018':'SiteInterconnection' },
          req:['transport_bandwidth','transport_latency','protection'],
          cue:/ (transport\w*|distan\w*|remote|interconnex\w*|interconnect\w*|relier|relie\w*|deux sites|2 sites|entre (les |nos |deux |2 )?sites|multi ?sites?|sites? distants?|datacenter\w*|data centers?|centres? de donnees|centres? de (supervision|traitement|controle|pilotage)|siege|backhaul|vpn|liaison\w*|liens?|wan|cloud|between (the |our |two )?sites|two sites|remote (site|data ?center|control center)) / },
};
const SUPPORT_BC = { 'BC-009':'edge', 'BC-010':'transport' };
const KIND_LABEL = {
  fr:{ edge:'Capacité edge', transport:'Capacité de transport', for:'au service de' },
  en:{ edge:'Edge capability', transport:'Transport capability', for:'serving' },
};

function tcPairs(f){const ids=Array.isArray(f.technical_capability_ids)?f.technical_capability_ids:[];const names=Array.isArray(f.technical_capability_names)?f.technical_capability_names:[];return ids.map((id,i)=>[String(id),names[i]??null]);}
function setTcs(f,pairs){const seen=new Set();const p=pairs.filter(([id])=>!seen.has(id)&&seen.add(id));f.technical_capability_ids=p.map(x=>x[0]);f.technical_capability_names=p.map(([id,n])=>n??SUPPORT.edge.tcs[id]??SUPPORT.transport.tcs[id]??null);}
function splitTcs(f){const out={edge:[],transport:[],other:[]};for(const pr of tcPairs(f)){if(pr[0] in SUPPORT.edge.tcs)out.edge.push(pr);else if(pr[0] in SUPPORT.transport.tcs)out.transport.push(pr);else out.other.push(pr);}return out;}
function isSupport(f){return f.categorie==='support'||!!SUPPORT_BC[f.business_capability_id];}
function kindOf(f){const s=splitTcs(f);if(SUPPORT_BC[f.business_capability_id])return SUPPORT_BC[f.business_capability_id];return s.edge.length?'edge':(s.transport.length?'transport':null);}
function normalizeShape(f){
  if(!Array.isArray(f.supports))f.supports=f.supports?[String(f.supports)]:[];
  f.supports=uniq(f.supports.map(x=>String(x).trim()).filter(Boolean));
  f.categorie=isSupport(f)?'support':'metier';
  if(f.categorie==='metier')f.supports=[];
  return f;
}
function setKind(f,kind,otherPairs){
  const K=SUPPORT[kind];
  f.categorie='support';f.business_capability_id=K.bc;f.business_capability_name=K.bcn;f.sous_type_5g=null;
  setTcs(f,[...splitTcs(f)[kind],...(otherPairs||[])]);
}
function takeReqKeys(f,keys){const out={};for(const k of keys){if(f.requirements&&Object.prototype.hasOwnProperty.call(f.requirements,k)){out[k]=f.requirements[k];delete f.requirements[k];}}return out;}
function nextId(funcs){const nums=funcs.map(f=>Number(String(f.id||'').replace(/^C/,''))).filter(Number.isFinite);return 'C'+((nums.length?Math.max(...nums):0)+1);}

// ctx = { msg, lang, baselineIds:Set|null, removedIds:Set, log:[] }
function deriveSupport(funcs, ctx){
  const L = KIND_LABEL[ctx.lang]||KIND_LABEL.fr;
  // preuve acceptée : un indice dans le message, OU (transport) au moins deux sites/régions distincts à relier
  const twoSites = r => Array.isArray(r?.regions) && new Set(r.regions.map(x => nrmTxt(x))).size >= 2;
  const cueOk = (kind, reqs) => SUPPORT[kind].cue.test(ctx.msg) || (kind === 'transport' && twoSites(reqs));
  const isKnown = f => !!ctx.baselineIds && ctx.baselineIds.has(f.id) && !f._new;
  const pending = [];

  // A. capacités support déclarées : une seule famille par capacité, preuve technique obligatoire
  for (const f of [...funcs]) {
    normalizeShape(f); normalizeReq(f);
    const parts = splitTcs(f);
    if (f.categorie === 'support') {
      const kinds = ['edge','transport'].filter(k => parts[k].length);
      if (!kinds.length) {
        funcs.splice(funcs.indexOf(f),1);
        ctx.log.push(`${f.id} écartée : capacité support sans capacité technique edge/transport (TC-013..TC-018)`);
        continue;
      }
      if (!isKnown(f) && !kinds.some(k => cueOk(k, f.requirements))) {
        funcs.splice(funcs.indexOf(f),1);
        ctx.log.push(`${f.id} écartée (prudence) : aucun indice edge/transport explicite dans le message`);
        continue;
      }
      const first = kinds.length === 2 ? (f.business_capability_id === 'BC-010' ? 'transport' : 'edge') : kinds[0];
      if (kinds.length === 2) {
        const second = first === 'edge' ? 'transport' : 'edge';
        const g = clone(f); g._new = true; g.id = nextId(funcs); g.derivation = { rule:'split_support', source:f.id };
        g.requirements = { ...(f.requirements?.regions ? { regions: clone(f.requirements.regions) } : {}), ...takeReqKeys(f, SUPPORT[second].req) };
        g.description = `${L[second]}${g.supports.length ? ' ' + L.for + ' ' + g.supports.join(', ') : ''}`;
        setKind(g, second, []);
        funcs.push(g);
        ctx.log.push(`${f.id} contenait edge ET transport : ${second} déplacé dans ${g.id}`);
      }
      setKind(f, first, parts.other);
    } else {
      // capacité métier portant des TC support et/ou des exigences réservées au support :
      // on les sort vers la capacité support correspondante (créée si besoin)
      setTcs(f, parts.other);
      for (const kind of ['edge','transport']) {
        const reqs = takeReqKeys(f, SUPPORT[kind].req);
        if (parts[kind].length || Object.keys(reqs).length) pending.push({ kind, source:f.id, tcs:parts[kind], reqs });
      }
    }
  }

  // B. dérivation : rattachement à un support existant, sinon création (si preuve + indice)
  for (const p of pending) {
    const src = funcs.find(x => x.id === p.source);
    const target = funcs.find(s => s.categorie === 'support' && kindOf(s) === p.kind && (s.supports||[]).includes(p.source));
    if (target) {
      setTcs(target, [...tcPairs(target), ...p.tcs]);
      Object.assign(target.requirements, clone(p.reqs));
      if (p.tcs.length) ctx.log.push(`${p.source} : ${p.tcs.map(x=>x[0]).join(',')} rattaché(es) au support ${target.id}`);
      continue;
    }
    if (!p.tcs.length || !cueOk(p.kind, src?.requirements)) {
      if (src) Object.assign(src.requirements, p.reqs);      // jamais perdu : reste sur la capacité métier
      if (p.tcs.length) ctx.log.push(`${p.source} : ${p.kind} non créé (prudence) — aucun indice explicite dans le message`);
      continue;
    }
    const K = SUPPORT[p.kind];
    const s = {
      id: nextId(funcs), _new: true,
      description: `${L[p.kind]} ${L.for} ${p.source}${src?.description ? ' (' + src.description + ')' : ''}`.slice(0, 300),
      categorie:'support', sous_type_5g:null,
      business_capability_id:K.bc, business_capability_name:K.bcn,
      technical_capability_ids:[], technical_capability_names:[],
      supports:[p.source],
      requirements:{ ...(src?.requirements?.regions ? { regions: clone(src.requirements.regions) } : {}), ...clone(p.reqs) },
      rationale: `derived: ${p.tcs.map(x=>x[0]).join(',')} on ${p.source}`,
      derivation:{ rule:'derived_from_business_capability', source:p.source, tcs:p.tcs.map(x=>x[0]), inherit_regions:true },
    };
    setTcs(s, p.tcs);
    funcs.push(s);
    ctx.log.push(`${s.id} créée : ${K.bcn} déduite de ${p.tcs.map(x=>x[0]).join(',')} sur ${p.source}`);
  }

  // C. liens "supports" : uniquement vers des capacités métier présentes ; cascade si toutes retirées
  const metierIds = new Set(funcs.filter(f => f.categorie === 'metier').map(f => f.id));
  for (const s of [...funcs]) {
    if (s.categorie !== 'support') continue;
    const before = s.supports || [];
    s.supports = uniq(before.filter(id => metierIds.has(id)));
    if (before.length && !s.supports.length && before.every(id => ctx.removedIds.has(id))) {
      funcs.splice(funcs.indexOf(s), 1);
      ctx.log.push(`${s.id} supprimée en cascade : ${before.join(',')} retirée(s)`);
    }
  }

  // D. un support dérivé suit les régions de la capacité métier qu'il sert (sauf modification explicite)
  for (const s of funcs) {
    if (s.categorie !== 'support' || !s.derivation?.inherit_regions || s.supports.length !== 1) continue;
    const src = funcs.find(x => x.id === s.supports[0]);
    if (src?.requirements?.regions) s.requirements.regions = clone(src.requirements.regions);
  }
  for (const f of funcs) applyAvailabilityTC(f);
  return funcs;
}

// =============================================================================
const intention=String($('Normalize Intent').first().json.intention||'');
const stateNode=$('Load Request State').first().json;
const current=stateNode.current_state;
const lang=String(stateNode.lang||'fr');
const userMsg=nrmTxt(stateNode.chatInput);
const derivation_log=[];
let o=null,err=null;
try{o=JSON.parse(clean($json.output));}catch(e){const raw=String($json.output??'');const cut=/Unterminated|Unexpected end|end of JSON input/i.test(e.message);err=(cut?'AGENT1A_OUTPUT_TRUNCATED':'AGENT1A_JSON_PARSE_ERROR')+': '+e.message+' | longueur='+raw.length+' | fin="'+raw.slice(-60).replace(/\s+/g,' ')+'"'+(cut?' | la reponse du modele a ete coupee : augmenter numCtx/numPredict ou reduire la taille de la demande':'');}
if(!err&&(!o||o.etape!=='1_agent1a'||o.mode!==intention))err='INVALID_AGENT1A_CONTRACT';
const strip=f=>{delete f._new;return f;};
const done=(out,extra)=>{for(const l of derivation_log)console.log('[1a-support] '+l);return [{json:{output:JSON.stringify(out),derivation_log,...extra}}];};

// --- Nouvelle demande ---
if(!err&&intention==='decomposition'){
  if(!Array.isArray(o.functionalities)||o.functionalities.length>MAX_FUNCS)err='INVALID_DECOMPOSITION_FUNCTIONALITIES';
  let funcs=[];
  if(!err){
    const idMap=new Map();
    o.functionalities.forEach((f,i)=>{if(f&&f.id!=null)idMap.set(String(f.id),'C'+(i+1));});
    for(let i=0;i<o.functionalities.length;i++){
      const f=clone(o.functionalities[i]);
      if(!f||typeof f!=='object'){err='INVALID_FUNCTIONALITY_'+(i+1);break;}
      if(!isSupport(f)&&(!f.business_capability_id||!f.business_capability_name)){err='INVALID_FUNCTIONALITY_'+(i+1);break;}
      f.id='C'+(i+1);f._new=true;
      f.supports=(Array.isArray(f.supports)?f.supports:[]).map(x=>idMap.get(String(x))).filter(Boolean);
      funcs.push(f);
    }
  }
  if(!err){
    deriveSupport(funcs,{msg:userMsg,lang,baselineIds:null,removedIds:new Set(),log:derivation_log});
    if(funcs.length>MAX_FUNCS)err='MAX_'+MAX_FUNCS+'_FUNCTIONALITIES';
    else if(!funcs.length)err='NO_USABLE_FUNCTIONALITY';
  }
  if(!err){
    // renumérotation C1..Cn (métier d'abord, puis support) et report sur "supports"
    funcs.sort((a,b)=>(a.categorie==='support')-(b.categorie==='support'));
    const ren=new Map(funcs.map((f,i)=>[f.id,'C'+(i+1)]));
    for(const f of funcs){f.supports=(f.supports||[]).map(id=>ren.get(id)).filter(Boolean);if(f.derivation?.source)f.derivation.source=ren.get(f.derivation.source)??f.derivation.source;}
    funcs=funcs.map(f=>strip(initNew(f,ren.get(f.id))));
  }
  const session=String(stateNode.sessionId||'default');
  const reqId='REQ-'+Date.now()+'-'+session.replace(/[^a-zA-Z0-9]/g,'').slice(-8);
  const out=err?{etape:'1_decomposition',mode:'decomposition',request_id:reqId,revision:1,portfolio_complete:false,functionalities:[],pipeline_error:err}:{etape:'1_decomposition',mode:'decomposition',request_id:reqId,revision:1,portfolio_complete:true,functionalities:funcs,pipeline_error:null};
  return done(out,{pipeline_ready:!err,pipeline_error:err,clarification_question:null});
}

// --- Complément ---
if(!err&&intention==='complement'){
  if(o.needs_clarification===true){const defQ=lang==='en'?'Could you clarify which capability is concerned?':'Pouvez-vous préciser la fonctionnalité concernée ?';return done({etape:'1_decomposition',mode:'complement',request_id:current?.request_id||null,revision:current?.revision||0,portfolio_complete:false,functionalities:[],pipeline_error:'NEEDS_CLARIFICATION'},{pipeline_ready:false,pipeline_error:'NEEDS_CLARIFICATION',clarification_question:String(o.clarification_question||defQ)});}
  if(!current||current.etape!=='3_catalogue'||current.portfolio_complete!==true||!Array.isArray(current.functionalities))err='MISSING_VALID_CURRENT_STATE';
  if(!err&&(!Array.isArray(o.operations)||o.operations.length===0))err='EMPTY_COMPLEMENT_OPERATIONS';
  if(!err&&o.operations.length>MAX_OPS)err='TOO_MANY_COMPLEMENT_OPERATIONS';
  if(err)return done({etape:'1_decomposition',mode:'complement',request_id:current?.request_id||null,revision:current?.revision||0,portfolio_complete:false,functionalities:[],pipeline_error:err},{pipeline_ready:false,pipeline_error:err,clarification_question:(lang==='en'?'I could not apply this addition without ambiguity. Please specify the capability or the constraint to modify.':'Je n’ai pas pu appliquer ce complément sans ambiguïté. Précisez la capacité ou la contrainte à modifier.')});

  let funcs=clone(current.functionalities).map(f=>markUnchanged(normalizeShape(f)));
  const baselineSig=new Map(funcs.map(f=>[f.id,signature(f)]));
  const baselineReq=new Map(funcs.map(f=>[f.id,clone(f.requirements||{})]));
  const baselineIds=new Set(funcs.map(f=>f.id));
  const removedIds=new Set();
  for(const op of o.operations){
    if(!op||!['add','update','remove'].includes(op.operation)){err='INVALID_COMPLEMENT_OPERATION';break;}
    if(op.operation==='remove'){
      const i=funcs.findIndex(f=>f.id===op.target_id);if(i<0){err='REMOVE_TARGET_NOT_FOUND_'+String(op.target_id);break;}removedIds.add(funcs[i].id);funcs.splice(i,1);continue;
    }
    if(op.operation==='add'){
      if(funcs.length>=MAX_FUNCS){err='MAX_'+MAX_FUNCS+'_FUNCTIONALITIES';break;}
      const nf=clone(op.functionality||{});
      if(!nf||typeof nf!=='object'||(!isSupport(nf)&&(!nf.business_capability_id||!nf.business_capability_name))){err='ADD_MISSING_BUSINESS_CAPABILITY';break;}
      normalizeShape(nf);
      const duplicate=funcs.some(f=>capKey(f)===capKey(nf)&&capKey(nf)!=='');if(duplicate){err='ADD_DUPLICATE_CAPABILITY_USE_UPDATE';break;}
      nf.id=nextId(funcs);nf._new=true;normalizeReq(nf);funcs.push(nf);continue;
    }
    const i=funcs.findIndex(f=>f.id===op.target_id);if(i<0){err='UPDATE_TARGET_NOT_FOUND_'+String(op.target_id);break;}
    const f=funcs[i];
    const reqBefore=clone(f.requirements&&typeof f.requirements==='object'&&!Array.isArray(f.requirements)?f.requirements:{});
    const fs=op.functionality_set&&typeof op.functionality_set==='object'&&!Array.isArray(op.functionality_set)?op.functionality_set:{};
    const allowed=['description','categorie','supports','sous_type_5g','business_capability_id','business_capability_name','technical_capability_ids','technical_capability_names','rationale'];
    for(const k of allowed){if(Object.prototype.hasOwnProperty.call(fs,k))f[k]=clone(fs[k]);}
    if(!f.requirements||typeof f.requirements!=='object'||Array.isArray(f.requirements))f.requirements={};
    const set=op.requirements_set&&typeof op.requirements_set==='object'&&!Array.isArray(op.requirements_set)?{...op.requirements_set}:{};
    const add=op.requirements_add&&typeof op.requirements_add==='object'&&!Array.isArray(op.requirements_add)?{...op.requirements_add}:{};
    const rem=op.requirements_remove&&typeof op.requirements_remove==='object'&&!Array.isArray(op.requirements_remove)?op.requirements_remove:{};
    // un support dont l'utilisateur modifie explicitement les régions ne suit plus celles de la capacité servie
    if(f.derivation&&['regions'].some(k=>k in set||k in add||k in rem))f.derivation.inherit_regions=false;
    // Garde-fou : « plutôt Paris », « remplace Lyon par Paris »… sans marqueur d'ajout => remplacement, pas union
    if(add.regions!==undefined&&set.regions===undefined&&REPLACE_CUE.test(userMsg)&&!ADD_CUE.test(userMsg)){const prevR=Array.isArray(reqBefore.regions)?reqBefore.regions:[];if(!prevR.some(r=>isNegated(userMsg,r))){set.regions=Array.isArray(add.regions)?add.regions:[add.regions];delete add.regions;}}
    for(const [k,v] of Object.entries(set))f.requirements[k]=clone(v);
    for(const [k,v] of Object.entries(add)){const vals=Array.isArray(v)?v:[v];const cur=Array.isArray(f.requirements[k])?f.requirements[k]:(f.requirements[k]===undefined?[]:[f.requirements[k]]);f.requirements[k]=[...new Set([...cur,...vals].map(x=>typeof x==='string'?x.trim():x))];}
    for(const [k,v] of Object.entries(rem)){if(v===null){delete f.requirements[k];continue;}const vals=Array.isArray(v)?v:[v];if(Array.isArray(f.requirements[k])){f.requirements[k]=f.requirements[k].filter(x=>!vals.some(y=>stable(x)===stable(y)));if(f.requirements[k].length===0)delete f.requirements[k];}else if(vals.some(y=>stable(f.requirements[k])===stable(y)))delete f.requirements[k];}
    if(op.rationale)f.rationale=String(op.rationale);
    normalizeReq(f);
    // Garde-fou : retirer toute région explicitement niée dans le message (« non pas Lyon », « plus à Lyon »)
    if(Array.isArray(f.requirements.regions)){f.requirements.regions=f.requirements.regions.filter(r=>!isNegated(userMsg,r));if(!f.requirements.regions.length)delete f.requirements.regions;}
  }
  if(!err){
    deriveSupport(funcs,{msg:userMsg,lang,baselineIds,removedIds,log:derivation_log});
    if(funcs.length>MAX_FUNCS)err='MAX_'+MAX_FUNCS+'_FUNCTIONALITIES';
    else if(!funcs.length)err='NO_USABLE_FUNCTIONALITY';
  }
  if(err)return done({etape:'1_decomposition',mode:'complement',request_id:current.request_id||null,revision:current.revision||0,portfolio_complete:false,functionalities:[],pipeline_error:err},{pipeline_ready:false,pipeline_error:err,clarification_question:(lang==='en'?('This addition is inconsistent with the active request ('+err+'). Please specify the desired change.'):('Le complément est incohérent avec la demande active ('+err+'). Précisez la modification souhaitée.'))});

  funcs=funcs.map(f=>{
    if(f._new||!baselineIds.has(f.id))return strip(initNew(f,f.id));
    const before=baselineReq.get(f.id)||{};
    const diff=[];for(const k of [...new Set([...Object.keys(before),...Object.keys(f.requirements||{})])]){if(stable(before[k]??null)!==stable(f.requirements[k]??null))diff.push({key:k,before:clone(before[k]??null),after:clone(f.requirements[k]??null)});}
    const changed=signature(f)!==baselineSig.get(f.id);
    const g=changed?resetImpacted(f):markUnchanged(f);
    if(diff.length)g.requirements_diff=diff;else delete g.requirements_diff;
    return strip(g);
  });
  const out={etape:'1_decomposition',mode:'complement',request_id:current.request_id,revision:Number(current.revision||1)+1,portfolio_complete:true,functionalities:funcs,pipeline_error:null};
  return done(out,{pipeline_ready:true,pipeline_error:null,clarification_question:null});
}

const finalErr=err||'UNSUPPORTED_INTENTION_FOR_AGENT1A';
return done({etape:'1_decomposition',mode:intention||null,request_id:current?.request_id||null,revision:current?.revision||0,portfolio_complete:false,functionalities:[],pipeline_error:finalErr},{pipeline_ready:false,pipeline_error:finalErr,clarification_question:null});

// ===== Assembler Agent 1b — robuste =====
// L'item source fait foi ; l'agent ne fournit que matched_generic_service + statut.
// Filet de sécurité : si la sortie LLM est vide, on prend le meilleur candidat réellement
// retourné par RAG_Generic_Services (option "Return Intermediate Steps" de l'agent).
const SRC_NODE='Prepare Grounding Items',STAGE='1b_matching',PFX='AGENT1B';
function genericCands(it){
  const out=[],add=(id,name,score)=>{if(id==null||id==='')return;id=String(id);if(!out.some(c=>c.id===id))out.push({id,name:name??null,score:num(score)});};
  for(const d of collectDocs(it)){const m=d.metadata;add(m.id??m.generic_id??m.service_id,m.name??m.generic_name,m.score);}
  if(!out.length){for(let s of obsTexts(it)){s=s.replace(/\\+"/g,'"');const re=/"id"\s*:\s*"?([\w.-]+)"?\s*,\s*"name"\s*:\s*"([^"]+)"/g;let m;while((m=re.exec(s)))add(m[1],m[2],null);}}
  return out;
}
function processOne(f,o,of,it){
  const idem=f.idempotence,cs=String(idem.capability_status||''),cur=String(idem.generic_service_status||'');
  let st,src;
  if(cs==='existing_unchanged'){
    // règle déterministe : aucun nouveau matching
    st=(f.matched_generic_service&&f.matched_generic_service.id!=null)?'existing_reused':(['not_found','tool_error'].includes(cur)?cur:'not_found');
    src='reused';
  }else{
