  if(cs==='existing_unchanged'){
    st=f.recommandations_metier?'existing_reused':(['not_found','tool_error','not_applicable'].includes(cur)?cur:'not_applicable');src='reused';
  }else if(!f.matched_generic_service||['not_found','tool_error'].includes(gss)){
    f.recommandations_metier=null;st='not_applicable';src='regle';
  }else{
    const docs=collectDocs(it),called=steps(it).length>0;
    let rec=null,ast=null;
    if(o){
      rec=has(o,'recommandations_metier')?o.recommandations_metier:of.recommandations_metier;
      ast=o.business_recommendation_status??o.idempotence?.business_recommendation_status??of.idempotence?.business_recommendation_status??null;
    }
