    rec=typeof rec==='string'&&rec.trim()?rec.trim():null;
    if(rec){st='new_match';src='agent';}
    else if(o&&['not_found','tool_error'].includes(String(ast))){st=String(ast);src='agent';}
    else if(docs.length&&(rec=excerpt(docs[0]))){st='new_match';src='rag_top1 (sortie agent vide/illisible)';}
    else if(called){rec=null;st=toolFailed(it)?'tool_error':'not_found';src='rag_vide';}
    else{rec=null;st='tool_error';src='outil non appelé + sortie vide';}
    f.recommandations_metier=rec;
  }
