// L'item source fait foi ; l'agent ne fournit que candidate_offers (0/1 CFS) + offer_status.
// Si la sortie LLM est vide : offre reconstruite depuis recommend_slice (spec_id/SLA/RFS réels),
// sinon depuis le meilleur résultat RAG_Service_Offerings Type=CFS et Orderable=YES.
const SRC_NODE='Prepare Discovery Items',STAGE='3_catalogue',PFX='AGENT3';
function mget(m,keys){const ks=Object.keys(m||{});for(const k of keys){const h=ks.find(x=>x.toLowerCase().replace(/[\s_-]/g,'')===k);if(h&&m[h]!=null&&m[h]!=='')return m[h];}return null;}
function isBundleDoc(m,txt){const b=mget(m,['isbundle','bundle']);if(b!=null)return /^(yes|true|1|oui)$/i.test(String(b));const t=mget(m,['type','spectype','category','kind']);if(t!=null&&/bundle/i.test(String(t)))return true;return /(Bundle|isBundle)\s*[:=]\s*(yes|true|oui)/i.test(txt)||/Type\s*[:=]\s*\S*bundle/i.test(txt);}
function bundleIds(it){const s=new Set();for(const d of collectDocs(it)){if(!isBundleDoc(d.metadata,d.pageContent||''))continue;const id=mget(d.metadata,['specid','servicespecid','uuid','id'])??(/spec_id\s*[:=]\s*([0-9a-f-]{36})/i.exec(d.pageContent||'')||[])[1];if(id)s.add(String(id));}return s;}
function catalogCands(it){
  const out=[];
  for(const d of collectDocs(it)){
    const m=d.metadata,txt=d.pageContent||'';
    let type=mget(m,['type','spectype','category','kind']);
    let ord=mget(m,['orderable','isorderable']);
    if(type==null){const x=/Type\s*[:=]\s*([A-Za-z]+)/i.exec(txt);type=x?x[1]:null;}
    if(ord==null){const x=/Orderable\s*[:=]\s*([A-Za-z]+)/i.exec(txt);ord=x?x[1]:null;}
    const id=mget(m,['specid','servicespecid','uuid','id'])??(/spec_id\s*[:=]\s*([0-9a-f-]{36})/i.exec(txt)||[])[1];
    const name=mget(m,['specname','servicespecname','name']);
    if(!id||!/CFS/i.test(String(type??''))||!/^(yes|true|1)$/i.test(String(ord??'')))continue;
    if(isBundleDoc(m,txt))continue;   // un bundle n'est jamais retenu pour UNE capacité
    if(!out.some(c=>c.spec_id===String(id)))out.push({spec_id:String(id),spec_name:name?String(name):null,score:num(mget(m,['score']))});
  }
  return out;
}
function sliceInfo(it){
  for(let s of obsTexts(it)){
    const p=deepParse(s);if(typeof p==='string')s=p;
    s=String(s).replace(/\\n/g,'\n');
    const id=/^\s*spec_id:\s*(\S+)/m.exec(s);if(!id||!/^\s*CFS:/m.test(s))continue;
    const name=(/^\s*CFS:\s*(.+)$/m.exec(s)||[])[1]?.trim()??null;
    let sla=null;const sl=/COMMITTED_SLA:\s*(.+)$/m.exec(s);
    if(sl){sla={};for(const kv of sl[1].split(/,\s*(?=[A-Za-z_]+=)/)){const i=kv.indexOf('=');if(i>0){const v=kv.slice(i+1).trim();sla[kv.slice(0,i).trim()]=v===''?null:v;}}}
    const rfs=[];const r=s.split(/REALIZED_BY \(RFS\):/)[1];
    if(r)for(const line of r.split('\n')){const x=/^\s*-\s*([^:]+?)(?::|$)/.exec(line);if(x)rfs.push(x[1].trim());}
