  }
  return null;
}
function processOne(f,o,of,it){
  const idem=f.idempotence,cs=String(idem.capability_status||''),cur=String(idem.offer_status||'');
  if(has(f,'offer_status'))delete f.offer_status;
  if(!Array.isArray(f.candidate_offers))f.candidate_offers=[];
  let st,src;
  const redo=idem.offer_rediscovery===true;delete idem.offer_rediscovery;
  if(cs==='existing_unchanged'&&!redo){
    if(f.candidate_offers.length>1)f.candidate_offers=f.candidate_offers.slice(0,1);
    st=f.candidate_offers.length===1?'existing_reused':(['not_found','tool_error','not_applicable'].includes(cur)?cur:'not_found');src='reused';
  }else if(!f.matched_generic_service){
    f.candidate_offers=[];st='not_applicable';src='regle';
  }else{
    let cands=catalogCands(it),sl=sliceInfo(it);const called=steps(it).length>0;
    let offers=null,ast=null;
    if(o){
      offers=Array.isArray(o.candidate_offers)?o.candidate_offers:(Array.isArray(of.candidate_offers)?of.candidate_offers:null);
      ast=o.offer_status??o.idempotence?.offer_status??of.idempotence?.offer_status??of.offer_status??null;
    }
    let off=offers&&offers.length?clone(offers[0]):null;
    if(off&&off.spec_id&&bundleIds(it).has(String(off.spec_id)))off=null;   // bundle proposé par l'agent : écarté
    if(off&&!off.spec_name&&off.name)off.spec_name=off.name;
    if(off&&off.spec_id){
      const known=(sl&&sl.spec_id===String(off.spec_id))||cands.some(c=>c.spec_id===String(off.spec_id)||(c.spec_name&&c.spec_name===off.spec_name));
      if(!known&&(sl||cands.length)){const c=sl||cands[0];off={spec_id:c.spec_id,spec_name:c.spec_name,score:c.score??null};src='outil (spec_id agent non retrouvé)';}
      else src='agent';
      st='new_match';
    }else if(o&&['not_found','tool_error'].includes(String(ast))&&!sl){off=null;st=String(ast);src='agent';}
    else if(sl){off={spec_id:sl.spec_id,spec_name:sl.spec_name,score:cands.find(c=>c.spec_id===sl.spec_id)?.score??null};st='new_match';src='recommend_slice (sortie agent vide/illisible)';}
    else if(cands.length){off={spec_id:cands[0].spec_id,spec_name:cands[0].spec_name,score:cands[0].score};st='new_match';src='rag_catalog_top1 (sortie agent vide/illisible)';}
    else if(called){off=null;st=toolFailed(it)?'tool_error':'not_found';src='rag_vide';}
    else{off=null;st='tool_error';src='outil non appelé + sortie vide';}
    if(off&&f.categorie==='support')sl=null;   // edge/transport : pas de recommend_slice, pas de SLA de slice
    if(off){
      const same=sl&&sl.spec_id===String(off.spec_id);
      off={spec_id:String(off.spec_id),spec_name:off.spec_name??(same?sl.spec_name:null),score:num(off.score),
           committed_sla:f.categorie==='support'?null:(off.committed_sla??(same?sl.committed_sla:null)),
           realized_by_rfs:f.categorie==='support'?[]:(Array.isArray(off.realized_by_rfs)&&off.realized_by_rfs.length?off.realized_by_rfs:(same?sl.realized_by_rfs:[]))};
    }
    f.candidate_offers=off?[off]:[];
  }
  idem.offer_status=st;
  if(f.candidate_offers.length===1&&!f.candidate_offers[0].spec_id)return 'AGENT3_OFFER_WITHOUT_SPEC_ID_'+f.id;
  if(f.candidate_offers.length===1&&!['new_match','existing_reused'].includes(st))return 'OFFER_STATUS_INCONSISTENT_'+f.id+'_'+st;
  if(f.candidate_offers.length===0&&!['not_found','tool_error','not_applicable'].includes(st))return 'EMPTY_OFFER_STATUS_INCONSISTENT_'+f.id+'_'+st;
  console.log(`[3] ${f.id}: ${f.candidate_offers[0]?.spec_name??'aucun CFS'} | ${st} | source=${src}`);
  return null;
}

