function collectDocs(it){const docs=[];for(const s of steps(it)){const walk=v=>{if(Array.isArray(v)){v.forEach(walk);return;}if(v&&typeof v==='object'){if(v.metadata&&typeof v.metadata==='object')docs.push({pageContent:String(v.pageContent??''),metadata:v.metadata});else Object.values(v).forEach(walk);}};walk(deepParse(s&&s.observation));}return docs;}
function toolFailed(it){return obsTexts(it).some(t=>/error|erreur|exception|ECONNREFUSED|timeout/i.test(t)&&!/metadata/i.test(t));}
function pairIndex(it,i){const p=Array.isArray(it.pairedItem)?it.pairedItem[0]:it.pairedItem;return typeof p==='number'?p:(p&&typeof p.item==='number'?p.item:i);}
function srcAll(name){try{return $(name).all();}catch(_){return [];}}
function num(v){const x=Number(v);return v!==null&&v!==''&&Number.isFinite(x)?x:null;}

// ---- cadre commun : association sortie agent <-> item source ----
let EXT={};
function out(o){return [{json:{output:JSON.stringify({...o,...EXT})}}];}
function fail(m,err){return out({etape:STAGE,mode:m?.mode??null,request_id:m?.request_id??null,revision:m?.revision??null,portfolio_complete:false,functionalities:[],pipeline_error:err});}
const items=$input.all();
const src=srcAll(SRC_NODE);
const rows=[];let err=null;
for(let i=0;i<items.length;i++){
  const it=items[i],k=pairIndex(it,i),base=src[k]?.json??null,o=tryParse(it.json.output),b=base??o;
  if(!b){err=PFX+'_ITEM_JSON_PARSE_ERROR: sortie agent vide et item source introuvable ('+SRC_NODE+')';break;}
  if(b.portfolio_complete===false&&b.pipeline_error){err=String(b.pipeline_error);break;}
  if(o&&o.item_error){err=String(o.item_error);break;}
  rows.push({it,o,b,k});
}
if(err||!rows.length)return fail(rows[0]?.b,err||PFX+'_NO_ITEMS');
const first=rows[0].b;
EXT=(first&&first.portfolio_ext&&typeof first.portfolio_ext==='object')?first.portfolio_ext:{};
if(rows.length===1&&first.empty_portfolio)return out({etape:STAGE,mode:first.mode,request_id:first.request_id,revision:first.revision,portfolio_complete:true,functionalities:[],pipeline_error:first.pipeline_error??null});
rows.sort((x,y)=>(x.b.index??x.k)-(y.b.index??y.k));
const funcs=[],ids=new Set();
for(const {it,o,b,k} of rows){
  if(!b.functionality||typeof b.functionality!=='object'){err=PFX+'_MISSING_FUNCTIONALITY';break;}
  const f=clone(b.functionality);
  if(!f.idempotence||typeof f.idempotence!=='object')f.idempotence={};
  if(!f.id||ids.has(f.id)){err=PFX+'_DUPLICATE_ID';break;}
  ids.add(f.id);
  const of=(o&&o.functionality&&typeof o.functionality==='object')?o.functionality:{};
  const e=processOne(f,o,of,it);
  if(e){err=e;break;}
  funcs.push(f);
}
if(err)return fail(first,err);
return out({etape:STAGE,mode:first.mode,request_id:first.request_id,revision:first.revision,portfolio_complete:true,functionalities:funcs,pipeline_error:first.pipeline_error??null});

// ===== État de la demande stocké dans le node "Request State Memory" =====
// (écrit par "Write State Memory", relu par "Read State Memory", clé = sessionId du chat)
const MEM_TAG = 'N8N_STATE_V8::';
function newRecord() { return { current: null, history: [], orders: [], updated_at: null }; }
function prevRecord() { const r = $('Load Request State').first().json.memory_record; return r && typeof r === 'object' ? JSON.parse(JSON.stringify(r)) : newRecord(); }
function toPayload(rec) { rec.updated_at = new Date().toISOString(); return MEM_TAG + JSON.stringify(rec); }
function specIdsOf(state) { return [...new Set((state?.functionalities || []).map(f => Array.isArray(f.candidate_offers) && f.candidate_offers[0] ? String(f.candidate_offers[0].spec_id || '') : '').filter(Boolean))].sort(); }
function obsTexts(json) { return (Array.isArray(json.intermediateSteps) ? json.intermediateSteps : []).map(s => { const o = s && s.observation; let t = typeof o === 'string' ? o : JSON.stringify(o ?? ''); try { const p = JSON.parse(t); if (typeof p === 'string') t = p; } catch (_) {} return t; }); }
// ================================================================================

// Prépare l'écriture en mémoire du portfolio final (sortie Agent 3 agrégée + validée).
// L'écriture effective est faite par "Write State Memory" (Chat Memory Manager -> Simple Memory).
let lang = 'fr';
try { lang = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}
const raw = String($json.output ?? '').trim();
let o;
try { o = JSON.parse(raw); } catch (e) { return [{ json: { output: (lang === 'en' ? 'Internal error: unable to save the portfolio (' : 'Erreur interne: impossible de sauvegarder le portfolio (') + e.message + ').', state_saved: false } }]; }
if (!o || o.etape !== '3_catalogue' || o.portfolio_complete !== true || !Array.isArray(o.functionalities))
  return [{ json: { output: (lang === 'en' ? 'Internal error: the final portfolio is not valid and was not saved.' : 'Erreur interne: le portfolio final n’est pas valide et n’a pas été sauvegardé.'), state_saved: false } }];

const old = prevRecord();
const snap = JSON.parse(JSON.stringify(o));
snap.saved_at = new Date().toISOString();
snap.spec_ids = specIdsOf(snap);   // CFS à commander, prêts pour Agent Commande

let history = Array.isArray(old.history) ? old.history : [];
if (old.current && old.current.request_id === snap.request_id) history = [...history, old.current].slice(-3);
else history = [];

const rec = { current: snap, history, orders: Array.isArray(old.orders) ? old.orders.slice(-20) : [] };
return [{ json: {
  output: JSON.stringify(snap),
  state_saved: true,
  memory_payload: toPayload(rec),
  request_id: snap.request_id,
  revision: snap.revision
} }];

// =============================================================================
// Node "Offer Presentation"  (Code — Run Once for All Items)          v7
// Structure :
//   **Proposition de services**
//   **1. Capacités et exigences identifiées** — par capacité : Description, Exigences,
//        Service générique, Recommandations
//   **2. Offre composite couvrant les N capacités** — bundle : capacité → CFS membre
//        (sans bundle : **2. Offres CFS retenues** — capacité → CFS unitaire)
//   **3. Confirmation de commande**
// Mise en forme : titres, sous-titres, clés, ids et noms de CFS en gras.
// Bilingue : la langue est celle détectée dans "Load Request State" (json.lang, fr|en).
// =============================================================================

const SHOW_SLA = false;           // sous-ligne "SLA offert" pour les offres unitaires (section 2 sans bundle)
const SHOW_CONFORMITY = true;     // sous-ligne "Respect des exigences" pour les offres UNITAIRES vérifiées (jamais pour un bundle)
const RECO_MAX_SENTENCES = 4;     // recommandations : nombre de phrases affichées

let LANG = 'fr';
try { LANG = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}
const EN = LANG === 'en';

const passthrough = { memory_payload: $json.memory_payload ?? null };
const err = m => [{ json: { ...passthrough, output: m } }];

const raw = String($json.output ?? '').trim();
let o;
try { o = JSON.parse(raw); } catch (e) { return err(EN ? 'Internal error: the final portfolio is unreadable.' : 'Erreur interne: le portfolio final est illisible.'); }
if (!o || o.etape !== '3_catalogue' || o.portfolio_complete !== true || !Array.isArray(o.functionalities))
  return err(EN ? 'Internal error: no complete portfolio can be presented.' : 'Erreur interne: aucun portfolio complet ne peut être présenté.');
if (!o.functionalities.length)
  return err(EN ? 'I did not identify any usable 5G capability in this request. Please clarify the need.' : 'Je n’ai identifié aucune capacité 5G exploitable dans cette demande. Précisez le besoin.');

// ---------- mise en forme -------------------------------------------------------
const C = EN ? ':' : ' :';                       // « Exigences : » (fr) / « Requirements: » (en)
const SEP = EN ? '; ' : ' ; ';
const b = s => `**${s}**`;                       // gras
const code = s => `**\`${s}\`**`;                // id en gras (et en police fixe)
const key = lbl => `* ${b(lbl)}${C}`;            // clé de puce en gras

// ---------- helpers ------------------------------------------------------------
const LBL_KPI_FR = { 'Latency':'latence', 'Number of terminals':'nombre de terminaux',
  'Maximum number of UEs':'nombre de terminaux', 'Area of service':'zone de service',
  'Reliability':'fiabilité', 'Availability':'disponibilité', 'Isolation level':'isolation',
  'UE density':'densité de terminaux', 'Downlink Throughput':'débit descendant',
  'Uplink Throughput':'débit montant', 'uEMobilityLevel':'mobilité', 'areaOfService':'zone de service',
  'Latency (Packet Delay Budget)':'latence (Packet Delay Budget)',
  'Slice quality of service: Packet Delay Budget':'latence (Packet Delay Budget)',
  'availability':'disponibilité', 'reliability':'fiabilité',
  'Downlink maximum throughput per UE':'débit descendant max par terminal',
  'Uplink maximum throughput per UE':'débit montant max par terminal',
  'Downlink guaranteed throughput per network slice':'débit descendant garanti (slice)',
  'Uplink guaranteed throughput per network slice':'débit montant garanti (slice)',
  'UE Density':'densité de terminaux', 'Price':'prix', 'Supported device velocity':'mobilité',
  'Slice quality of service parameters (priority)':'priorité du trafic',
  'Jitter':'gigue', 'Survival time':'temps de survie', 'Maximum supported packet size':'taille de paquet',
  'Transmission interval':'intervalle de transmission', 'Positioning support':'positionnement',
  'Positional accuracy':'précision de positionnement', 'Data volume':'volume de données',
  'User data access':'chiffrement' };
const LBL_KPI_EN = { 'Latency':'latency', 'Number of terminals':'number of terminals',
  'Maximum number of UEs':'number of terminals', 'Area of service':'service area',
  'Reliability':'reliability', 'Availability':'availability', 'Isolation level':'isolation',
  'UE density':'UE density', 'Downlink Throughput':'downlink throughput',
  'Uplink Throughput':'uplink throughput', 'uEMobilityLevel':'mobility', 'areaOfService':'service area',
  'Latency (Packet Delay Budget)':'latency (Packet Delay Budget)',
  'Slice quality of service: Packet Delay Budget':'latency (Packet Delay Budget)',
  'availability':'availability', 'reliability':'reliability',
  'Downlink maximum throughput per UE':'max downlink throughput per UE',
  'Uplink maximum throughput per UE':'max uplink throughput per UE',
  'Downlink guaranteed throughput per network slice':'guaranteed downlink throughput (slice)',
  'Uplink guaranteed throughput per network slice':'guaranteed uplink throughput (slice)',
  'UE Density':'UE density', 'Price':'price', 'Supported device velocity':'mobility',
  'Slice quality of service parameters (priority)':'traffic priority',
  'Jitter':'jitter', 'Survival time':'survival time', 'Maximum supported packet size':'packet size',
  'Transmission interval':'transmission interval', 'Positioning support':'positioning support',
  'Positional accuracy':'positioning accuracy', 'Data volume':'data volume',
  'User data access':'encryption' };
const LBL_KPI = EN ? LBL_KPI_EN : LBL_KPI_FR;

const ZONE_PFX = 'Area of Service: Region specification — ';
const kpi = l => {
  const s = String(l ?? '');
  const st = /^(.*?)( \[[A-Z_]+\])$/.exec(s);          // suffixe de statut [UNKNOWN_UNIT]…
  const base = st ? st[1] : s, suf = st ? st[2] : '';
  if (base.startsWith(ZONE_PFX)) return 'zone ' + base.slice(ZONE_PFX.length) + suf;
  return (LBL_KPI[base] || base) + suf;
};

// Recommandations : quelques phrases utiles, sans en-tête ni mise en page de document source
function recoLine(txt) {
  let t = String(txt || '').replace(/\s+/g, ' ').trim();
  if (!t) return null;
  const phrases = t.split(/(?<=[.!?])\s+/)
    .filter(s => s.split(' ').length >= 6)
    .filter(s => !/\||CONFIDENTIAL|Internal Use Only|Page \d|§|^\s*\d+\.|NST-\d|Use case\s*:|S-NSSAI|TS \d{2}\.\d{3}|v\d+\.\d+\.\d+/i.test(s));
  const keep = phrases.slice(0, RECO_MAX_SENTENCES).join(' ').trim();
  return keep.length >= 25 ? keep : null;
}

// Codes d'isolation du catalogue (GST) -> libellé
const ISO_LABELS = { '0':'No Isolation', '1':'Physical Isolation', '2':'Logical Isolation' };
const isoLabel = v => {
  const s = String(v ?? '').trim();
  if (!s) return s;
  if (/[a-z]/i.test(s)) return s;                                  // déjà un libellé
  return ISO_LABELS[s] ? `${ISO_LABELS[s]} (${s})` : (EN ? `code ${s} (not listed)` : `code ${s} (non répertorié)`);
};

function slaLine(sla) {
  if (sla === null || sla === undefined) return null;
  if (typeof sla === 'string') return sla.slice(0, 200);
  const M_FR = { sST:'type', latency_ms:'latence', latency:'latence', reliability:'fiabilité',
              availability:'disponibilité', Availability:'disponibilité', isolation:'isolation',
              maxUEs:'terminaux max', mobility:'mobilité', throughput:'débit' };
  const M_EN = { sST:'type', latency_ms:'latency', latency:'latency', reliability:'reliability',
              availability:'availability', Availability:'availability', isolation:'isolation',
              maxUEs:'max terminals', mobility:'mobility', throughput:'throughput' };
  const M = EN ? M_EN : M_FR;
  const parts = [];
  for (const [k, v] of Object.entries(sla)) {
    if (v === null || v === undefined || v === '' || v === 'undefined' || v === 'null') continue;
    let val = v;
    if (k === 'latency_ms') val = Number(v) >= 1000 ? (Number(v) / 1000) + ' s' : v + ' ms';
    else if (k === 'reliability' || k === 'availability' || k === 'Availability')
      val = EN ? (String(v) + (/%/.test(String(v)) ? '' : ' %')) : (String(v).replace('.', ',') + (/%/.test(String(v)) ? '' : ' %'));
    else if (k === 'maxUEs') { const n = Number(v); val = Number.isFinite(n) ? n.toLocaleString(EN ? 'en-US' : 'fr-FR') : v; }
    else if (k === 'isolation' || k === 'isolationLevel') val = isoLabel(v);
    parts.push(`${M[k] || k} ${val}`);
  }
  return parts.length ? parts.join(' · ') : null;
}

const VERDICT = { PASS: '✅', PASS_WITH_GAPS: '🟠', FAIL: '❌', ERROR: '⚠️', NOT_VERIFIED: '⚪' };
function conformityLine(f) {
  const cf = f.conformity;
  if (!cf || !cf.verdict) return EN ? '⚪ not verified' : '⚪ non vérifié';
  const v = cf.verdict;
  if (v === 'NOT_VERIFIED' || v === 'ERROR') {
    const jamais = (cf.unverified_requirements || []).map(kpi);
    return EN
      ? `${VERDICT[v]} not verified${jamais.length ? ' — ' + jamais.join(', ') : ''}`
      : `${VERDICT[v]} non vérifié${jamais.length ? ' — ' + jamais.join(', ') : ''}`;
  }
  const seg = [];
  const ok = (cf.satisfied || []).map(kpi);
  if (ok.length) seg.push((EN ? 'met: ' : 'respectées : ') + ok.join(', '));
  const isIso = c => /isolation/i.test(String(c.kpi || c.label || ''));
  const expShow = c => {
    const e = Array.isArray(c.expected) ? c.expected : [c.expected];
    const txt = e.map(x => isIso(c) ? isoLabel(x) : x).join(EN ? ' or ' : ' ou ');
    return c.op === 'in' ? txt : `${c.op} ${txt}`;
  };
  const ko = (cf.checks || []).filter(c => c.status === 'FAIL')
    .map(c => EN
      ? `${kpi(c.label || c.kpi)} (required ${expShow(c)}${c.unit ? ' ' + c.unit : ''}, offered ${isIso(c) ? isoLabel(c.actual) : (c.actual ?? '—')})`
      : `${kpi(c.label || c.kpi)} (exigé ${expShow(c)}${c.unit ? ' ' + c.unit : ''}, offert ${isIso(c) ? isoLabel(c.actual) : (c.actual ?? '—')})`);
  if (ko.length) seg.push((EN ? 'not met: ' : 'non respectées : ') + ko.join(', '));
  const nd = (cf.undocumented || []).map(kpi);
  if (nd.length) seg.push((EN ? 'not documented in catalog: ' : 'non documentées au catalogue : ') + nd.join(', '));
  const nv = (cf.unverified_requirements || []).map(kpi);
  if (nv.length) seg.push((EN ? 'not verified: ' : 'non vérifiées : ') + nv.join(', '));
  return `${VERDICT[v] || ''} ${seg.join(' · ') || (EN ? 'no requirement to verify' : 'aucune exigence à vérifier')}`;
}

// ---------- exigences : libellé + opérateur + valeur + unité --------------------
const T = EN ? {
  latency:'latency', e2e_latency:'end-to-end latency', jitter:'jitter', throughput:'throughput', dl:'downlink throughput', ul:'uplink throughput',
  availability:'availability', reliability:'reliability', device_count:'number of devices', user_count:'number of users',
  vehicle_count:'number of vehicles', device_density:'device density', isolation:'isolation', mobility:'mobility',
  device_velocity:'device velocity', positioning:'positioning', positioning_accuracy:'positioning accuracy',
  packet_size:'packet size', transmission_interval:'transmission interval', coverage:'coverage', data_volume:'data volume',
  encryption:'encryption', compute:'compute', storage:'storage', edge_location:'edge location',
  transport_bandwidth:'transport bandwidth', transport_latency:'transport latency', protection:'protection', regions:'service area',
} : {
  latency:'latence', e2e_latency:'latence de bout en bout', jitter:'gigue', throughput:'débit', dl:'débit descendant', ul:'débit montant',
  availability:'disponibilité', reliability:'fiabilité', device_count:'nombre d’équipements', user_count:'nombre d’utilisateurs',
  vehicle_count:'nombre de véhicules', device_density:'densité d’équipements', isolation:'isolation', mobility:'mobilité',
  device_velocity:'vitesse des équipements', positioning:'positionnement', positioning_accuracy:'précision de positionnement',
  packet_size:'taille de paquet', transmission_interval:'intervalle de transmission', coverage:'couverture', data_volume:'volume de données',
  encryption:'chiffrement', compute:'calcul', storage:'stockage', edge_location:'emplacement edge',
  transport_bandwidth:'débit de transport', transport_latency:'latence de transport', protection:'protection', regions:'zone de service',
};
const OPS = { '<':'<', '<=':'≤', '=':'=', '>=':'≥', '>':'>' };
const cap1 = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const num = v => (typeof v === 'number' && !EN) ? String(v).replace('.', ',') : String(v);
const E2E = /bout en bout|end[- ]to[- ]end|aller[- ]retour|round[- ]trip/i;

function reqLabel(k, v) {
  const dir = v && typeof v === 'object' ? v.direction : null;
  if (k === 'throughput') return dir === 'downlink' ? T.dl : dir === 'uplink' ? T.ul : T.throughput;
  if (k === 'latency' && v && E2E.test(String(v.quote || ''))) return T.e2e_latency;
  return T[k] || String(k).replace(/_/g, ' ');
}
function reqText(label, v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v !== 'object') return `${label}${C} ${v}`;
  const has = v.value !== undefined && v.value !== null && v.value !== '';
  if (!has) return v.quote ? String(v.quote) : null;
  if (typeof v.value === 'string' && !/^[\d.,]+$/.test(v.value)) return `${label}${C} ${v.value}`;      // qualitatif
  const op = OPS[v.operator] || '';
  const unit = v.unit ? ' ' + v.unit : '';
  return `${label} ${op ? op + ' ' : ''}${num(v.value)}${unit}`.replace(/\s+/g, ' ').trim();
}
// « de Paris et de Lyon » / « d’Annecy » — liste lisible de sites
const deSite = n => EN ? n : (/^[aeiouyhâàéèêîôûAEIOUYHÂÀÉÈÊÎÔÛ]/.test(n) ? 'd’' + n : 'de ' + n);
const joinList = (a, f = x => x) => { const l = a.map(f); return l.length <= 1 ? (l[0] || '') : l.slice(0, -1).join(', ') + (EN ? ' and ' : ' et ') + l[l.length - 1]; };
const SUPPORT_TC = EN ? {
  'TC-013':'data processing close to the site', 'TC-014':'computation offloaded to the network edge',
  'TC-015':'local breakout of the traffic', 'TC-016':'traffic kept local to the site',
} : {
  'TC-013':'traitement des données à proximité du site', 'TC-014':'déport de calcul vers la périphérie du réseau',
  'TC-015':'local breakout du trafic', 'TC-016':'trafic maintenu en local sur le site',
};
function requirementsOf(f) {
  const r = (f.requirements && typeof f.requirements === 'object') ? f.requirements : {};
  const out = [];
  const regions = Array.isArray(r.regions) ? r.regions.filter(Boolean) : [];
  const isTransport = f.business_capability_id === 'BC-010';
  for (const [k, v] of Object.entries(r)) {
    if (k === 'regions') continue;
    if (k === 'extra') {
      for (const e of (Array.isArray(v) ? v : [])) {
        if (!e) continue;
        const t = typeof e === 'object' ? reqText(String(e.raw_key || '').trim() || (EN ? 'requirement' : 'exigence'), e) : String(e);
        if (t) out.push(t);
      }
      continue;
    }
    const t = reqText(reqLabel(k, v), v);
    if (t) out.push(t);
  }
  // capacités support sans exigence chiffrée : la capacité technique tient lieu d'exigence
  if (f.categorie === 'support' && !isTransport) {
    for (const id of (f.technical_capability_ids || [])) if (SUPPORT_TC[id] && !out.length) out.push(SUPPORT_TC[id]);
  }
  const prio = t => /^(débit|throughput|downlink|uplink)/i.test(t) ? 0 : /latence|latency/i.test(t) ? 1 : 2;
  out.sort((a, c) => prio(a) - prio(c));
  if (isTransport && regions.length >= 2) {
    out.unshift(EN ? `interconnection between the ${joinList(regions)} sites` : `interconnexion entre les sites ${joinList(regions, deSite)}`);
  } else if (regions.length) {
    out.push(`${T.regions}${C} ${regions.join(', ')}`);
  }
  return out;
}

// ---------- offre composite (bundle) -------------------------------------------
const B = o.bundle_offer && o.bundle_offer.spec_id ? o.bundle_offer : null;
const NUM_WORDS = EN ? ['zero','one','two','three','four','five','six','seven','eight']
                     : ['zéro','une','deux','trois','quatre','cinq','six','sept','huit'];
const nWord = n => NUM_WORDS[n] || String(n);
const capTitle = f => `${f.id} — ${f.business_capability_name || (EN ? 'Capability' : 'Capacité')}`;

// ---------- rendu -------------------------------------------------------------
const L = [];
const sec = (n, t) => { L.push(''); L.push(b(`${n}. ${t}`)); };
L.push(o.mode === 'complement'
  ? b(EN ? `Updated service proposal (revision ${o.revision})` : `Proposition de services mise à jour (révision ${o.revision})`)
  : b(EN ? 'Service proposal' : 'Proposition de services'));

let n = 1;

// ---------- section 1 : capacités et exigences ---------------------------------
sec(n++, EN ? 'Identified capabilities and requirements' : 'Capacités et exigences identifiées');

for (const f of o.functionalities) {
  const cs = String(f?.idempotence?.capability_status || '');
  const tag = o.mode === 'complement'
    ? (cs === 'new' ? (EN ? ' _[new]_' : ' _[nouvelle]_')
      : cs === 'existing_updated' ? (EN ? ' _[updated]_' : ' _[mise à jour]_')
      : cs === 'existing_unchanged' ? (EN ? ' _[unchanged]_' : ' _[conservée]_') : '')
    : '';
  const sup = f.categorie === 'support' && (f.supports || []).length
    ? (EN ? ` (support for ${joinList(f.supports)})` : ` (support de ${joinList(f.supports)})`) : '';
  L.push('');
  L.push(`${b(capTitle(f) + sup)}${tag}`);
  L.push('');

  if (f.description) L.push(`${key('Description')} ${f.description}`);

  const reqs = requirementsOf(f);
  L.push(reqs.length
    ? `${key(EN ? 'Requirements' : 'Exigences')} ${cap1(reqs.join(SEP))}.`
    : `${key(EN ? 'Requirements' : 'Exigences')} ${EN ? 'No explicit performance requirement expressed.' : 'Aucune exigence de performance explicite exprimée.'}`);

  if (o.mode === 'complement' && Array.isArray(f.requirements_diff) && f.requirements_diff.length) {
    const show = (k, v) => { if (v === null || v === undefined) return '—'; if (Array.isArray(v)) return v.join(', ') || '—';
      const t = reqText(reqLabel(k, v), v); return t ? t.replace(reqLabel(k, v), '').trim() || t : '—'; };
    const mods = f.requirements_diff.map(d => `${reqLabel(d.key, d.after || d.before)}${C} ${show(d.key, d.before)} → ${show(d.key, d.after)}`);
    L.push(`${key(EN ? 'Changes' : 'Modifications')} ${mods.join(SEP)}.`);
  }

  const gs = f.matched_generic_service;
  L.push(gs && gs.id != null
    ? `${key(EN ? 'Generic service' : 'Service générique')} ${code(`${gs.id} — ${gs.name || (EN ? 'unnamed' : 'sans nom')}`)}.`
    : `${key(EN ? 'Generic service' : 'Service générique')} ${EN ? 'No generic service identified.' : 'Aucun service générique identifié.'}`);

  const reco = recoLine(f.recommandations_metier);
  L.push(`${key(EN ? 'Recommendations' : 'Recommandations')} ${reco || (EN ? 'Not available for this capability.' : 'Non disponibles pour cette capacité.')}`);
}

// ---------- section 2 : offre composite ou offres CFS unitaires ----------------
const orderSpecs = new Map();   // spec_id -> nom (ce qui sera commandé)
if (B) {
  orderSpecs.set(String(B.spec_id), B.spec_name || B.spec_id);
  const coveredIds = (B.covered_functionalities && B.covered_functionalities.length) ? B.covered_functionalities : o.functionalities.map(f => f.id);
  const covered = o.functionalities.filter(f => coveredIds.includes(f.id));
  const nw = nWord(covered.length);
  sec(n++, EN ? `Composite offer covering the ${nw} capabilities` : `Offre composite couvrant les ${nw} capacités`);
  L.push('');
  L.push(EN
    ? `The composite offer ${b(B.spec_name || B.spec_id)} (${code(B.spec_id)}) covers the ${nw} capabilities identified in part 1 through the following CFS:`
    : `L’offre composite ${b(B.spec_name || B.spec_id)} (${code(B.spec_id)}) couvre les ${nw} capacités identifiées dans la partie 1 grâce aux CFS suivants :`);
  L.push('');
  for (const f of covered) {
    const m = (B.members || []).find(x => (x.covers || []).includes(f.id))
           || (Array.isArray(f.candidate_offers) && f.candidate_offers[0] ? f.candidate_offers[0].bundle_member : null);
    L.push(m && m.spec_id
      ? `* ${b(capTitle(f))} → ${b(m.spec_name || m.spec_id)} (${code(m.spec_id)}).`
      : `* ${b(capTitle(f))} → ${EN ? 'member CFS not identified.' : 'CFS membre non identifié.'}`);
  }
} else {
  sec(n++, EN ? 'Selected CFS offers' : 'Offres CFS retenues');
  L.push('');
  const noBundle = ['not_found', 'rejected', 'tool_error'].includes(o.bundle_status);
  L.push(noBundle
    ? (EN ? `No composite offer in the catalog covers all the capabilities${o.bundle_note ? ' (' + o.bundle_note + ')' : ''}. Each capability is served by its own CFS:`
          : `Aucune offre composite du catalogue ne couvre l’ensemble des capacités${o.bundle_note ? ' (' + o.bundle_note + ')' : ''}. Chaque capacité est servie par son propre CFS :`)
    : (EN ? 'Each capability identified in part 1 is served by the following CFS:'
          : 'Chaque capacité identifiée dans la partie 1 est servie par le CFS suivant :'));
  L.push('');
  for (const f of o.functionalities) {
    const of = Array.isArray(f.candidate_offers) ? f.candidate_offers[0] : null;
    if (of && of.spec_id) {
      const name = of.spec_name || of.name || of.spec_id;
      orderSpecs.set(String(of.spec_id), name);
      L.push(`* ${b(capTitle(f))} → ${b(name)} (${code(of.spec_id)}).`);
      if (SHOW_SLA) { const s = slaLine(of.committed_sla); if (s) L.push(`  * ${b(EN ? 'Committed SLA' : 'SLA offert')}${C} ${s}.`); }
      if (SHOW_CONFORMITY && f.conformity && f.conformity.verdict && f.conformity.verdict !== 'NOT_VERIFIED')
        L.push(`  * ${b(EN ? 'Compliance with requirements' : 'Respect des exigences')}${C} ${conformityLine(f)}`);
    } else {
      L.push(`* ${b(capTitle(f))} → ${EN ? 'no orderable offer found.' : 'aucune offre orderable trouvée.'}`);
    }
  }
}

// ---------- section finale : confirmation -------------------------------------
sec(n++, EN ? 'Order confirmation' : 'Confirmation de commande');
L.push('');
if (orderSpecs.size) {
  const names = [...orderSpecs.values()].map(b);
  L.push(B
    ? (EN ? `If you confirm, the bundle ${b(B.spec_name || B.spec_id)} will be ordered in a single TMF641 Service Order.`
          : `Si vous confirmez, le bundle ${b(B.spec_name || B.spec_id)} sera commandé dans une seule Service Order TMF641.`)
    : orderSpecs.size === 1
      ? (EN ? `If you confirm, the CFS ${names[0]} will be ordered in a single TMF641 Service Order.`
            : `Si vous confirmez, le CFS ${names[0]} sera commandé dans une seule Service Order TMF641.`)
      : (EN ? `If you confirm, the ${orderSpecs.size} selected CFS (${joinList(names)}) will be grouped into a single TMF641 Service Order.`
            : `Si vous confirmez, les ${orderSpecs.size} CFS retenus (${joinList(names)}) seront regroupés dans une seule Service Order TMF641.`));
  const anyFail = !B && o.functionalities.some(f => f?.conformity?.verdict === 'FAIL');
  L.push('');
  L.push(anyFail
    ? (EN ? 'At least one offer does not meet your requirements. Would you like to (a) order anyway, (b) relax the requirement in question, or (c) have me search for another offer?'
          : 'Au moins une offre ne satisfait pas vos exigences. Souhaitez-vous (a) commander malgré tout, (b) assouplir l’exigence en cause, ou (c) que je recherche une autre offre ?')
    : (EN ? 'Do you confirm the order?' : 'Confirmez-vous la commande ?'));
} else {
  L.push(EN ? 'No order can be created until an orderable CFS is available.'
            : 'Aucune commande ne peut être créée tant qu’aucun CFS orderable n’est disponible.');
}

return [{ json: { ...passthrough, output: L.join('\n') } }];

// Renvoie au chat le texte du chemin qui vient de s'exécuter (après l'écriture en mémoire).
for (const n of ['Offer Presentation', 'Activate Service Order', 'Deployment Reply', 'Tracking Reply']) {
  try { if ($(n).isExecuted) return [{ json: { output: String($(n).first().json.output ?? '') } }]; } catch (e) {}
}
let lang = 'fr';
try { lang = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}
return [{ json: { output: lang === 'en' ? 'Response unavailable.' : 'Réponse indisponible.' } }];

// =============================================================================
// Node "CFS Verification Preparation"  (Code — Run Once for All Items)   v3
// Entrée : sortie true de "Discovery Valid?"  -> { output: <portfolio 3_catalogue> }
// Sortie : 1 item par fonctionnalité ->
//          { ref, candidateId, requirements[], sparql, _portfolio, _meta }
//
// v3 : la requête SPARQL est construite ICI (et transmise à verify-cfs via
//      l'entrée `sparql`) :
//   - conversion d'unité à partir de tmf:unitOfMeasure, côté catalogue, vers
//     l'unité canonique de l'exigence (rate→Mbps, time→ms, pct→%, money→EUR,
//     density→/km2 ; count sans unité)
//   - zones : correspondance EXACTE par élément sur le code (tmf:value), l'alias
//     (tmf:valueAlias) ne sert qu'en repli si tmf:value ne contient aucun code
//   - projection identique à l'ancienne : ?candidate ?nameN ?valueN ?statusN
//   - statuts : PASS | FAIL | MISSING | UNPARSABLE | MISSING_UNIT | UNKNOWN_UNIT
// =============================================================================

// ── Unités catalogue -> facteur vers l'unité canonique ──────────────────────
// Clés = unitOfMeasure en minuscules, sans espaces ni ponctuation (sauf / % € ² µ).
// Complétez avec le résultat de la requête « SELECT DISTINCT ?unit » sur le catalogue :
// toute unité absente produit UNKNOWN_UNIT (jamais de comparaison silencieusement fausse).
const TO_CANON = {
  rate:    { 'bps':1e-6, 'bit/s':1e-6, 'b/s':1e-6, 'bitspersecond':1e-6,
             'kbps':1e-3, 'kbit/s':1e-3, 'kb/s':1e-3, 'kilobitspersecond':1e-3, 'kilobitpersecond':1e-3,
             'mbps':1, 'mbit/s':1, 'mb/s':1, 'megabitspersecond':1, 'megabitpersecond':1,
             'gbps':1e3, 'gbit/s':1e3, 'gb/s':1e3, 'gigabitspersecond':1e3, 'gigabitpersecond':1e3 },
  time:    { 'seconds':1e3, 'second':1e3, 'sec':1e3, 's':1e3,
             'milliseconds':1, 'millisecond':1, 'msec':1, 'ms':1,
             'microseconds':1e-3, 'microsecond':1e-3, 'us':1e-3, 'µs':1e-3, 'μs':1e-3 },
  pct:     { '%':1, 'percent':1, 'percentage':1, 'pourcent':1, 'pourcentage':1 },
  money:   { 'eur':1, '€':1, 'euro':1, 'euros':1 },
  density: { '/km2':1, 'ue/km2':1, 'ues/km2':1, 'perkm2':1, 'uesperkm2':1, 'ueperkm2':1,
             '/km²':1, 'ue/km²':1, 'ues/km²':1, 'km2':1, 'km²':1 },
};
const COUNT_FAMILIES = new Set(['count']);   // pas de conversion d'unité

const TMF  = 'http://vocab.nfmust.ie/tmf-service-core#';
const CFSB = 'http://vocab.nfmust.ie/tmf-service-core/concret_cfs/';
const nz   = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const lit  = s => '"' + String(s).replace(/\\/g,'\\\\').replace(/"/g,'\\"') + '"';
const num  = n => { const x = Number(n); return Number.isInteger(x) ? x + '.0' : String(x); };   // littéral xsd:decimal/double

function charSubquery(i, cand, name, withUnit, withAlias) {
  return `
  OPTIONAL {
    SELECT ?candidate (SAMPLE(?v) AS ?raw${i})${withUnit ? ` (SAMPLE(?u) AS ?rawU${i})` : ''}${withAlias ? ` (SAMPLE(?a) AS ?alias${i})` : ''} WHERE {
      VALUES ?candidate { <${cand}> }
      ?candidate tmf:hasCharacteristic ?c .
      ?c tmf:name ?n . FILTER(LCASE(STR(?n)) = LCASE(${lit(name)}))
      ?c tmf:hasCharacteristicValue ?cv .
      ?cv tmf:value ?v .${withUnit ? `
      OPTIONAL { ?cv tmf:unitOfMeasure ?u }` : ''}${withAlias ? `
      OPTIONAL { ?cv tmf:valueAlias ?a }` : ''}
    } GROUP BY ?candidate
  }`;
}

function cmp(lhs, op, value) {
  const v = num(value);
  // Tolérance : 0.005 s * 1000 vaut 5.000000000000001 en IEEE 754. Sans elle, une
  // offre pile à la limite basculerait au hasard sur les opérateurs non stricts.
  const eps = num(Math.max(Math.abs(Number(value)) * 1e-9, 1e-12));
  switch (op) {
    case '<':  return `${lhs} < ${v}`;
    case '<=': return `${lhs} <= ${v} + ${eps}`;
    case '>':  return `${lhs} > ${v}`;
    case '>=': return `${lhs} >= ${v} - ${eps}`;
    default:   return `ABS(${lhs} - ${v}) < ${eps}`;
  }
}

function numericBlock(i, cand, r) {
  const noUnit = COUNT_FAMILIES.has(r.family) || !TO_CANON[r.family];
  const head = charSubquery(i, cand, r.kpi, !noUnit, false) + `
  BIND(xsd:double(REPLACE(REPLACE(STR(?raw${i}), ",", "."), "[^0-9.eE+-]", "")) AS ?num${i})
  BIND(${lit(r.kpi)} AS ?name${i})`;
  if (noUnit) {
    return head + `
  BIND(STR(?raw${i}) AS ?value${i})
  BIND(IF(!BOUND(?raw${i}), "MISSING",
       IF(!BOUND(?num${i}), "UNPARSABLE",
       IF(${cmp(`?num${i}`, r.op, r.value)}, "PASS", "FAIL"))) AS ?status${i})`;
  }
  // facteur de conversion : -1 = unité inconnue
  const factor = Object.entries(TO_CANON[r.family]).reverse()
    .reduce((acc, [u, f]) => `IF(?u${i} = ${lit(u)}, ${num(f)}, ${acc})`, '-1.0');
  return head + `
  BIND(LCASE(REPLACE(STR(?rawU${i}), "[^A-Za-z0-9²µμ/%€]", "")) AS ?u${i})
  BIND(${factor} AS ?f${i})
  BIND(?num${i} * ?f${i} AS ?canon${i})
  BIND(IF(BOUND(?rawU${i}) && ?f${i} > 0,
       CONCAT(STR(ROUND(?canon${i} * 1000000) / 1000000), " ", ${lit(r.unit || '')}, " (", STR(?raw${i}), " ", STR(?rawU${i}), ")"),
       IF(BOUND(?rawU${i}), CONCAT(STR(?raw${i}), " ", STR(?rawU${i})), STR(?raw${i}))) AS ?value${i})
  BIND(IF(!BOUND(?raw${i}), "MISSING",
       IF(!BOUND(?rawU${i}), "MISSING_UNIT",
       IF(?f${i} < 0, "UNKNOWN_UNIT",
       IF(!BOUND(?num${i}), "UNPARSABLE",
       IF(${cmp(`?canon${i}`, r.op, r.value)}, "PASS", "FAIL"))))) AS ?status${i})`;
}

function zoneBlock(i, cand, r) {
  const code  = ',' + nz(r.value) + ',';
  const alias = ',' + nz(r.value_alias) + ',';
  return charSubquery(i, cand, r.kpi, false, true) + `
  BIND(CONCAT(",", REPLACE(LCASE(STR(?raw${i})), "[^a-z0-9,]", ""), ",") AS ?tv${i})
  BIND(CONCAT(",", REPLACE(LCASE(STR(?alias${i})), "[^a-z0-9,]", ""), ",") AS ?ta${i})
  BIND(${lit(r.kpi)} AS ?name${i})
  BIND(IF(BOUND(?alias${i}), CONCAT(STR(?raw${i}), " (", STR(?alias${i}), ")"), STR(?raw${i})) AS ?value${i})
  BIND(IF(!BOUND(?raw${i}), "MISSING",
       IF(CONTAINS(?tv${i}, ${lit(code)}), "PASS",
       IF(!CONTAINS(?tv${i}, ",fr") && BOUND(?alias${i}) && CONTAINS(?ta${i}, ${lit(alias)}), "PASS", "FAIL"))) AS ?status${i})`;
}

function categoricalBlock(i, cand, r) {
  const vals = Array.isArray(r.value) ? r.value : [r.value];
  const test = vals.map(v => `LCASE(STR(?raw${i})) = LCASE(${lit(v)})`).join(' || ');
  return charSubquery(i, cand, r.kpi, false, false) + `
  BIND(${lit(r.kpi)} AS ?name${i})
  BIND(STR(?raw${i}) AS ?value${i})
  BIND(IF(!BOUND(?raw${i}), "MISSING",
       IF(${test}, "PASS", "FAIL")) AS ?status${i})`;
}

function buildSparql(candidateId, reqs) {
  const cand = CFSB + candidateId;
  const vars = reqs.map((_, i) => `?name${i} ?value${i} ?status${i}`).join(' ');
  const blocks = reqs.map((r, i) =>
    r.kind === 'zone'   ? zoneBlock(i, cand, r) :
    r.kind === 'number' ? numericBlock(i, cand, r) :
                          categoricalBlock(i, cand, r)).join('\n');
  return `PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX tmf: <${TMF}>
SELECT ?candidate ${vars}
WHERE {
  VALUES ?candidate { <${cand}> }${blocks}
}`;
}

// ── Portfolio -> items ───────────────────────────────────────────────────────
const RAW = String($input.first().json.output ?? '').trim();
let p;
try { p = JSON.parse(RAW); } catch (e) {
  return [{ json: { ref:'__error__', candidateId:null, requirements:[], sparql:'', _portfolio:RAW,
                    _meta:{ skip_reason:'CONFORMITY_PREP_PARSE_ERROR: ' + e.message } } }];
}
if (!p || !Array.isArray(p.functionalities)) {
  return [{ json: { ref:'__error__', candidateId:null, requirements:[], sparql:'', _portfolio:RAW,
                    _meta:{ skip_reason:'CONFORMITY_PREP_INVALID_PORTFOLIO' } } }];
}

const items = [];
for (const f of p.functionalities) {
  const offer   = Array.isArray(f.candidate_offers) ? f.candidate_offers[0] : null;
  const aligned = Array.isArray(f.requirements_aligned) ? f.requirements_aligned : [];

  // Vérifiable = aligné ET présent dans l'ontologie
  const constraints = aligned
    .filter(c => c.in_ontology && c.attribute)
    .map(c => ({
      kpi: c.attribute, op: c.op, value: c.value,
      label: c.kind === 'zone' ? `${c.gst} — ${c.zone_label}` : (c.gst || c.attribute),
      unit: c.unit || '',
      kind: c.kind, family: c.family ?? null,
      ...(c.kind === 'zone' ? { value_alias: c.value_alias } : {}),
      blocking: c.blocking !== false,
      source_key: c.source_key ?? null, source_value: c.source_quote ?? c.source_value ?? null,
    }));

  // Aligné sur un attribut standard mais absent de l'ontologie -> non vérifiable, jamais perdu
  const notVerifiable = aligned.filter(c => !c.in_ontology)
    .map(c => ({ key: c.source_key, gst: c.gst, quote: c.source_quote ?? null }));

  const meta = { spec_name: offer?.spec_name ?? null, unmapped: notVerifiable, skip_reason: null };
  if (!offer || !offer.spec_id)   meta.skip_reason = 'aucun_cfs_retenu';
  else if (offer.is_bundle)      meta.skip_reason = 'couvert_par_bundle';   // vérification ontologie des bundles : plus tard
  else if (!constraints.length)   meta.skip_reason = 'aucune_exigence_verifiable';

  const reqs = meta.skip_reason ? [] : constraints;
  items.push({ json: {
    ref: f.id,
    candidateId: offer?.spec_id ?? null,
    requirements: reqs,
    sparql: reqs.length ? buildSparql(String(offer.spec_id), reqs) : '',
    _portfolio: RAW,
    _meta: meta,
  } });
  console.log(`[CONF] ${f.id} -> ${offer?.spec_id ?? 'aucun CFS'} : ${reqs.length} vérifiable(s), ${notVerifiable.length} hors ontologie`);
}

if (!items.length) items.push({ json: { ref:'__empty__', candidateId:null, requirements:[], sparql:'',
  _portfolio:RAW, _meta:{ skip_reason:'portfolio_vide', unmapped:[] } } });

return items;

// =============================================================================
// Node "Assemble CFS Verification"   (Code — Run Once for All Items)              v3
// Entrée  : N items = retours de verify-cfs ({ ref, verdict, checks[], ... })
// Sortie  : 1 item { output: "<portfolio 3_catalogue enrichi>", conformity_summary }
//
// Correctif v3 : le recalcul défensif du verdict n'utilisait que les checks
// bloquants, ce qui ramenait à PASS un verdict PASS_WITH_GAPS. De plus, les
// exigences jamais vérifiées (non alignées, ou alignées mais absentes de
// l'ontologie) n'avaient aucun effet : un CFS pouvait être annoncé conforme
// alors que 2 exigences sur 3 n'avaient jamais été contrôlées.
// =============================================================================

const PREP = 'CFS Verification Preparation';

const RAW = String($(PREP).first().json._portfolio ?? '').trim();
let p;
try { p = JSON.parse(RAW); } catch (e) {
  return [{ json: { output: RAW, conformity_summary: { error: 'PORTFOLIO_UNREADABLE' } } }];
}

const byRef = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  const ref = j.ref ?? j.functionality_id ?? null;
  if (ref) byRef.set(String(ref), j);
}
const prepItems = $(PREP).all().map(i => i.json);
if (!byRef.size) {
  const results = $input.all().map(i => i.json);
  prepItems.forEach((pi, k) => { if (results[k]) byRef.set(String(pi.ref), results[k]); });
}
const metaByRef = new Map(prepItems.map(pi => [String(pi.ref), pi._meta || {}]));

const GAP_STATUSES = ['MISSING', 'UNPARSABLE', 'MISSING_UNIT', 'UNKNOWN_UNIT'];
const ORDRE = { PASS: 0, PASS_WITH_GAPS: 1, NOT_VERIFIED: 2, ERROR: 3, FAIL: 4 };
let pire = 'PASS', nbFail = 0, nbGaps = 0, nbVerif = 0;

for (const f of p.functionalities) {
  const r    = byRef.get(String(f.id)) || null;
  const meta = metaByRef.get(String(f.id)) || {};
  const checks = Array.isArray(r?.checks) ? r.checks : [];

  let verdict;
  if (!r)                                      verdict = 'NOT_VERIFIED';
  else if (r.verdict)                          verdict = String(r.verdict);
  else if (r.error || r.message === undefined) verdict = 'ERROR';
  else                                         verdict = 'NOT_VERIFIED';
  if (verdict === 'SKIPPED') verdict = 'NOT_VERIFIED';
  if (meta.skip_reason === 'couvert_par_bundle') verdict = 'NOT_VERIFIED';

  // Recalcul défensif : même règle que verify-cfs (tous les checks comptent)
  if (checks.length && meta.skip_reason !== 'couvert_par_bundle') {
    const hardFail = checks.some(c => c.blocking !== false && c.status === 'FAIL');
    const softFail = checks.some(c => c.blocking === false && c.status === 'FAIL');
    const gaps     = checks.some(c => GAP_STATUSES.includes(c.status));
    verdict = hardFail ? 'FAIL' : (softFail || gaps) ? 'PASS_WITH_GAPS' : 'PASS';
  }

  const satisfied    = checks.filter(c => c.status === 'PASS').map(c => c.label || c.kpi);
  const unsatisfied  = checks.filter(c => c.status === 'FAIL' && c.blocking !== false).map(c => c.label || c.kpi);
  const soft         = checks.filter(c => c.status === 'FAIL' && c.blocking === false).map(c => c.label || c.kpi);
  const undocumented = checks.filter(c => GAP_STATUSES.includes(c.status))
    .map(c => (c.label || c.kpi) + (c.status === 'MISSING' ? '' : ` [${c.status}]`));

  // Exigences jamais contrôlées : alignées mais hors ontologie + jamais alignées
  const horsOntologie = (meta.unmapped || []).map(u => u.gst || u.key || u.quote).filter(Boolean);
  const nonAlignees   = (Array.isArray(f.requirements_unaligned) ? f.requirements_unaligned : [])
                          .map(u => u.quote || u.source_key).filter(Boolean);
  const nonVerifiees  = [...horsOntologie, ...nonAlignees];

  // Un CFS ne peut pas être déclaré pleinement conforme si des exigences n'ont jamais été contrôlées
  if (verdict === 'PASS' && nonVerifiees.length) verdict = 'PASS_WITH_GAPS';

  f.conformity = {
    verdict,
    checked_at: new Date().toISOString(),
    source: 'ontologie_graphdb/nfmust_catalog',
    candidate_id: r?.candidateId ?? (Array.isArray(f.candidate_offers) && f.candidate_offers[0]
      ? f.candidate_offers[0].spec_id : null),
    checks,
    satisfied,
    unsatisfied,
    soft_unsatisfied: soft,
    undocumented,
    not_verifiable: meta.unmapped || [],
    unverified_requirements: nonVerifiees,
    skip_reason: meta.skip_reason ?? r?.skip_reason ?? null,
    engine_error: r?.error ?? null,
  };
  f.idempotence = f.idempotence || {};
  f.idempotence.conformity_status = verdict;

  if (verdict !== 'NOT_VERIFIED') nbVerif++;
  if (verdict === 'FAIL') nbFail++;
  if (verdict === 'PASS_WITH_GAPS') nbGaps++;
  if (ORDRE[verdict] > ORDRE[pire]) pire = verdict;
  console.log(`[CONF] ${f.id}: ${verdict} | ok=[${satisfied}] | non satisfaites=[${unsatisfied}]`
    + ` | non bloquantes=[${soft}] | non documentées=[${undocumented}] | jamais vérifiées=[${nonVerifiees}]`);
}

p.conformity_overall = pire;

return [{ json: {
  output: JSON.stringify(p),
  conformity_summary: { overall: pire, verified: nbVerif, failed: nbFail, with_gaps: nbGaps },
} }];

// =============================================================================
// Node "GST Alignment"   (Code — Run Once for All Items)   v2
//
// Position : entre "Decomposition Merge" et "Decomposition Valid?"
