// ─────────────────────────────────────────────────────────────────────────────
// 1. RÉFÉRENTIEL DES ZONES — copie stricte du catalogue. Ne rien y ajouter
//    qui ne figure pas au catalogue.
// ─────────────────────────────────────────────────────────────────────────────
const ZONES = {
  'FR-PAR': { alias:'Paris',         villes:['Paris','La Defense','Aubervilliers','Saint-Denis','Boulogne'],
              pop:['Paris-Centre','La Defense','Aubervilliers'] },
  'FR-IDF': { alias:'Ile-de-France', villes:['Velizy','Saclay','Massy','Roissy','Noisy-le-Grand','Cergy'],
              pop:['Velizy','Saclay','Roissy','Massy'] },
  'FR-NE':  { alias:'Nord Est',      villes:['Lille','Strasbourg','Metz','Nancy','Reims','Dijon'],
              pop:['Lille','Strasbourg','Metz','Nancy','Reims'] },
  'FR-NW':  { alias:'Nord Ouest',    villes:['Rennes','Nantes','Rouen','Caen','Brest','Le Havre'],
