};

// ─────────────────────────────────────────────────────────────────────────────
// 2. TABLE D'ALIGNEMENT  besoin ──► attribut GST ──► littéral tmf:name
//    onto: null = attribut standard absent de l'ontologie (aligné, non vérifiable)
//    family : famille d'unité, utilisée par la conversion SPARQL
