                  alias:['latence','latency','delai','delay','tempsdereponse','responsetime','rtt','allerretour','roundtrip','e2elatency','packetdelaybudget'] },
  jitter:       { onto:null, gst:'Jitter', kind:'number', unit:'ms', dir:'max', family:'time',
                  alias:['gigue','jitter','variationdedelai','delayvariation'] },
  survival:     { onto:null, gst:'Survival time', kind:'number', unit:'ms', dir:'max', family:'time',
                  alias:['tempsdesurvie','survivaltime','survie'] },
  availability: { onto:'availability', gst:'Availability', kind:'number', unit:'%', dir:'min', family:'pct',
                  alias:['disponibilite','availability','dispo','uptime','tauxdedisponibilite'] },
  reliability:  { onto:'reliability', gst:'Reliability', kind:'number', unit:'%', dir:'min', family:'pct',
                  alias:['fiabilite','reliability','tauxdesucces','successrate'] },
  dl_thr_ue:    { onto:'Downlink maximum throughput per UE: Maximum downlink throughput per UE value',
