  ul_thr_ue:    { onto:'Uplink maximum throughput per UE: Maximum Uplink Throughput per UE value',
                  gst:'Uplink maximum throughput per UE', kind:'number', unit:'Mbps', dir:'min', family:'rate',
                  alias:['debitmontantparue','uplinkperue'] },
  dl_thr_slice: { onto:'Downlink throughput per network slice: Guaranteed downlink throughput quota',
                  gst:'Downlink guaranteed throughput per network slice', kind:'number', unit:'Mbps', dir:'min', family:'rate',
                  alias:['debitdescendant','downlink','debitglobal','debitagrege','bandepassante','bandwidth'] },
  ul_thr_slice: { onto:'Uplink throughput per network slice: Guaranteed uplink throughput quota',
                  gst:'Uplink guaranteed throughput per network slice', kind:'number', unit:'Mbps', dir:'min', family:'rate',
                  alias:['debitmontant','uplink','remontee'] },
  terminals:    { onto:'Maximum number of UEs', gst:'Maximum number of UEs', kind:'number', unit:'count', dir:'min', family:'count', invert:true,
                  alias:['nombredequipements','nombredeterminaux','nombredappareils','nombredeues','nombredecapteurs','nombrederobots','nombredevehicules','nombredutilisateurs','nombredecameras','devicecount','usercount','vehiclecount','numberofterminals','parcinstalle'] },
  density:      { onto:'UE Density', gst:'UE Density', kind:'number', unit:'/km2', dir:'min', family:'density',
                  alias:['densite','density','densitedequipements','ueparkm2','terminaldensity'] },
  price:        { onto:'Price', gst:'Price', kind:'number', unit:'EUR', dir:'max', family:'money',
                  alias:['prix','price','budget','cout','tarif'] },
  isolation:    { onto:'isolationLevel', gst:'Isolation level', kind:'string', family:'cat',
                  alias:['isolation','isolationlevel','cloisonnement','etancheite','dedie','exclusivite'] },
  mobility:     { onto:'uEMobilityLevel', gst:'Supported device velocity', kind:'string', family:'cat',
                  alias:['mobilite','mobility','deplacement','uemobility','niveaudemobilite'] },
  region:       { onto:'Area of Service: Region specification', gst:'Area of Service: Region specification',
                  kind:'zone', family:'geo',
                  alias:['zone','zonedeservice','zonedecouverture','areaofservice','region','regions','ville','site','lieu','emplacement','perimetre','couverture','coverage'] },
  priority:     { onto:null, gst:'Slice quality of service parameters (priority)', kind:'string', family:'cat',
                  alias:['priorite','prioritaire','priority','prioritization','prioritisation','qos'] },
  packet_size:  { onto:null, gst:'Maximum supported packet size', kind:'number', unit:'byte', dir:'max', family:'size',
                  alias:['taillepaquet','taillemaxpaquet','packetsize','mtu'] },
  interval:     { onto:null, gst:'Transmission interval', kind:'number', unit:'ms', dir:'max', family:'time',
                  alias:['periodicite','intervalle','transmissioninterval','frequencedemesure','periode'] },
  velocity:     { onto:null, gst:'Supported device velocity', kind:'number', unit:'km/h', dir:'min', family:'speed',
                  alias:['vitesse','velocite','velocity','speed','kmh'] },
  positioning:  { onto:null, gst:'Positioning support', kind:'string', family:'cat',
                  alias:['positionnement','positioning','geolocalisation','localisation'] },
  pos_accuracy: { onto:null, gst:'Positional accuracy', kind:'number', unit:'m', dir:'max', family:'length',
                  alias:['precisiondeposition','precisiondelocalisation','positionalaccuracy'] },
  data_volume:  { onto:null, gst:'Data volume', kind:'number', unit:'GB', dir:'min', family:'volume',
                  alias:['volumededonnees','datavolume','quotadedonnees'] },
  encryption:   { onto:null, gst:'User data access', kind:'string', family:'cat',
                  alias:['chiffrement','encryption','cryptage','confidentialite'] },
};

// Clés canoniques d'Agent 1a -> attribut (le débit dépend de scope/direction : voir resolveKey)
const KEYMAP = {
  regions:'region', coverage:'region',
  latency:'latency', jitter:'jitter', availability:'availability', reliability:'reliability',
  device_count:'terminals', user_count:'terminals', vehicle_count:'terminals',
  device_density:'density', isolation:'isolation', mobility:'mobility',
  device_velocity:'velocity', positioning:'positioning', positioning_accuracy:'pos_accuracy',
  packet_size:'packet_size', transmission_interval:'interval', data_volume:'data_volume',
  encryption:'encryption', traffic_priority:'priority', budget:'price',
};

const UNIT_FAMILY = {
  time:['latency','jitter','survival','interval'],
  rate:['dl_thr_ue','ul_thr_ue','dl_thr_slice','ul_thr_slice'],
  pct:['availability','reliability'],
  count:['terminals'], density:['density'], speed:['velocity'],
  length:['pos_accuracy'], size:['packet_size'], volume:['data_volume'], money:['price'],
};

// Lexiques catégoriels — ALIGNEZ ces littéraux sur ceux réellement stockés dans GraphDB
// Isolation : le catalogue stocke des CODES (0 = No Isolation, 1 = Physical, 2 = Logical).
// Une exigence accepte plusieurs codes -> opérateur "in".
const LEX = {
  isolationLevel: [[/(physique|physical|materiel|complet|total|dedie|dedicated|strict|exclusi)/,['1']],
                   [/(logique|logical|partage|shared|virtuel)/,['2','1']],
                   [/(aucun|sansisolation|noisolation|none)/,['0','1','2']]],
  uEMobilityLevel:[[/(stationn|fixe|static|immobile)/,'STATIONARY'],
                   [/(nomad)/,'NOMADIC'],
                   [/(restreint|restricted|limite)/,'RESTRICTED'],
                   [/(complet|full|elevee|high|vehicul|vehicular|mobile)/,'FULL']],
};

// Indices de flux MONTANT quand Agent 1a n'a pas donné de direction
const UPLINK_CUE = /(montant|uplink|remontee|upload|televers|videosurveillance|videoprotection|camera|cctv|vers(le|la|les|un|une|notre|nos)?(centre|serveur|cloud|datacenter|supervision|plateforme|pc))/;
const DOWNLINK_CUE = /(descendant|downlink|telecharg|download|streamingversles|diffusionversles)/;

// ─────────────────────────────────────────────────────────────────────────────
// 3. Helpers
// ─────────────────────────────────────────────────────────────────────────────
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/[^a-z0-9]/g,'');
const words = s => ' ' + String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/[^a-z0-9]+/g,' ').trim() + ' ';

const ALIAS = (() => { const m = new Map();
  for (const [id,a] of Object.entries(ATTRS)) { m.set(norm(id), id); for (const x of a.alias||[]) m.set(norm(x), id); }
  return m; })();

const ZONE_INDEX = (() => { const m = new Map();
  for (const [code, z] of Object.entries(ZONES))
    for (const k of [code, z.alias, ...z.villes, ...z.pop]) m.set(norm(k), code);
  return m; })();
function resolveZone(place) {
  const code = ZONE_INDEX.get(norm(place));
  return code ? { code, alias: ZONES[code].alias } : null;
}
const ZONE_LIST = Object.entries(ZONES).map(([c,z]) => `${z.alias} (${c})`).join(', ');

function unitFamily(u) {
  const x = norm(u);
  if (!x) return null;
  if (/^(ms|milliseconde|millisecond|s|sec|second|seconde|us|micro|microseconde|min|minute)s?$/.test(x)) return 'time';
  if (/(bit|bps|bs$)/.test(x)) return 'rate';
  if (/^(pourcent|percent|pct)$/.test(x) || String(u).trim() === '%') return 'pct';
  if (/km2|km²|parkm2/.test(x)) return 'density';
  if (/^(kmh|kmparh|mph)$/.test(x)) return 'speed';
  if (/^(m|metre|meter|cm|centimetre)s?$/.test(x)) return 'length';
  if (/^(o|octet|octets|byte|bytes|ko|kb|kilooctet)$/.test(x)) return 'size';
  if (/^(go|gb|to|tb|gio|gigaoctet)$/.test(x)) return 'volume';
  if (/^(eur|euro|euros)$/.test(x) || /€/.test(String(u))) return 'money';
  return null;
}
// Conversion de la valeur EXIGÉE vers l'unité canonique de l'attribut
function toTarget(attr, value, rawUnit) {
  const u = norm(rawUnit), n = Number(value);
  if (!Number.isFinite(n)) return null;
  switch (attr.unit) {
    case 'ms':   if (/^(s|sec|second|seconde)s?$/.test(u)) return n*1000;
                 if (/^(us|micro)/.test(u))                return n/1000;
                 if (/^(min|minute)/.test(u))              return n*60000;
                 return n;
    case 'Mbps': if (/^g/.test(u)) return n*1000;
                 if (/^k/.test(u)) return n/1000;
                 if (/^(bps|bits|bit)$/.test(u)) return n/1e6;
                 if (/(octet|byte)/.test(u) || /^mo/.test(u)) return n*8;   // Mo/s -> Mbit/s
                 return n;
    case 'byte': if (/^k/.test(u)) return n*1024;
                 if (/^m/.test(u)) return n*1048576;
                 return n;
    case 'GB':   if (/^t/.test(u)) return n*1000;
                 if (/^m/.test(u)) return n/1000;
                 return n;
    case 'm':    if (/^cm/.test(u)) return n/100;
                 if (/^km/.test(u)) return n*1000;
                 return n;
    default:     return n;   // %, count, /km2, km/h, EUR
  }
}
function opFor(attr, userOp) {
  if (attr.invert) return '>=';                       // "jusqu'à 150 UE" -> l'offre doit en supporter >= 150
  const o = String(userOp || '').trim();
  if (attr.dir === 'max') return ['<','<='].includes(o) ? o : '<=';
  if (attr.dir === 'min') return ['>','>='].includes(o) ? o : '>=';
  return o || '=';
}
function lexValue(ontoName, text) {
  const lex = LEX[ontoName]; if (!lex) return String(text);
  const t = norm(text);
  for (const [re,v] of lex) if (re.test(t)) return v;
  return null;
}
// Accepte l'ancien format ("<10 ms", 150) comme le nouveau (objet)
function coerce(raw) {
  if (raw && typeof raw === 'object' && !Array.isArray(raw))
    return { operator: raw.operator ?? null, value: raw.value ?? null, unit: raw.unit ?? null,
             scope: raw.scope ?? null, direction: raw.direction ?? null, quote: raw.quote ?? null };
  if (typeof raw === 'number') return { operator:null, value:raw, unit:null, scope:null, direction:null, quote:String(raw) };
  const s = String(raw ?? '').trim();
  const m = /^(<=|>=|=<|=>|<|>|=|≤|≥)?\s*([0-9][0-9\s\u00a0\u202f]*(?:[.,][0-9]+)?)\s*(.*)$/.exec(s);
  if (!m) return { operator:'=', value:s, unit:null, scope:null, direction:null, quote:s };
  let op = m[1] || null; if (op === '≤' || op === '=<') op = '<='; if (op === '≥' || op === '=>') op = '>=';
  let n = m[2].replace(/[\s\u00a0\u202f]/g,'');
  n = (n.includes(',') && !n.includes('.')) ? n.replace(',','.') : n.replace(/,/g,'');
  return { operator:op, value:Number(n), unit:(m[3]||'').trim()||null, scope:null, direction:null, quote:s };
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. Résolution du nom (4 couches, de la plus sûre à la plus faible)
// ─────────────────────────────────────────────────────────────────────────────
function throughputId(r, key, fdesc) {
  const w = words((r.quote || '') + ' ' + key);
  const perUe = r.scope === 'per_ue'
    || /\b(par|per) (robot|ue|equipement|appareil|device|utilisateur|user|vehicule|terminal|capteur|camera|drone)s?\b/.test(w);
  let uplink;
  if (r.direction === 'uplink') uplink = true;
  else if (r.direction === 'downlink') uplink = false;
  else {
    const q = norm(r.quote || ''), d = norm(fdesc || '');
    if (UPLINK_CUE.test(q)) uplink = true;
    else if (DOWNLINK_CUE.test(q)) uplink = false;
    else uplink = UPLINK_CUE.test(d) && !DOWNLINK_CUE.test(d);
  }
  return uplink ? (perUe ? 'ul_thr_ue' : 'ul_thr_slice') : (perUe ? 'dl_thr_ue' : 'dl_thr_slice');
}

function resolveKey(key, r, fdesc) {
  const ctx = norm((r.quote || '') + ' ' + key);

  // (1) clé canonique connue
  if (key === 'throughput' || key === 'bandwidth') return { id: throughputId(r, key, fdesc), how:'known_key' };
  if (KEYMAP[key]) return { id: KEYMAP[key], how:'known_key' };

  // (2) alias exact sur la clé brute (bucket "extra")
  if (ALIAS.has(norm(key))) {
    const id = ALIAS.get(norm(key));
    if (UNIT_FAMILY.rate.includes(id)) return { id: throughputId(r, key, fdesc), how:'alias' };
    return { id, how:'alias' };
  }

  // (3) alias trouvé dans la citation utilisateur
  for (const [a,id] of ALIAS) if (a.length >= 5 && ctx.includes(a)) {
    if (UNIT_FAMILY.rate.includes(id)) return { id: throughputId(r, key, fdesc), how:'alias_quote' };
    return { id, how:'alias_quote' };
  }

  // (4) désambiguïsation par l'unité
  const fam = unitFamily(r.unit);
  if (fam) {
    if (fam === 'rate') return { id: throughputId(r, key, fdesc), how:'unit_default' };
    const cands = UNIT_FAMILY[fam] || [];
    if (cands.length === 1) return { id: cands[0], how:'unit' };
    const hit = cands.filter(id => (ATTRS[id].alias || []).some(a => ctx.includes(norm(a))));
    if (hit.length === 1) return { id: hit[0], how:'unit_context' };
    if (fam === 'time') return { id:'latency', how:'unit_default' };
    if (fam === 'pct')  return { id: /(fiab|reliab|succes)/.test(ctx) ? 'reliability' : 'availability', how:'unit_default' };
  }
  return null;
}

function alignOne(key, raw, aligned, unaligned, fdesc) {
  const r = coerce(raw);
  const hit = resolveKey(key, r, fdesc);
  if (!hit) { unaligned.push({ source_key:key, source_value:r.value, source_unit:r.unit,
                               quote:r.quote, reason:'aucun_attribut_correspondant' }); return; }

  const a = ATTRS[hit.id];
  const base = { attribute:a.onto, gst:a.gst, in_ontology: !!a.onto, kind:a.kind, family:a.family,
                 source_key:key, source_operator:r.operator, source_value:r.value,
                 source_unit:r.unit, source_quote:r.quote, match:hit.how,
                 blocking: a.blocking !== false && !!a.onto };

  if (a.kind === 'zone') {
    const place = r.value ?? r.quote;
    const z = resolveZone(place);
    if (!z) {
      unaligned.push({ source_key:key, source_value:place, source_unit:null,
        quote:`zone « ${place} » hors référentiel catalogue (zones : ${ZONE_LIST})`,
        reason:'zone_hors_referentiel' });
      return;
    }
    aligned.push({ ...base, op:'contains', value:z.code, value_alias:z.alias, unit:'',
                   zone_label:`${z.alias} (${z.code})` });
    return;
  }

  if (a.kind === 'number') {
    const v = toTarget(a, r.value, r.unit);
    if (v === null) { unaligned.push({ source_key:key, quote:r.quote, reason:'valeur_non_numerique' }); return; }
    const op = opFor(a, r.operator);
    aligned.push({ ...base, op, value:v, unit:a.unit,
                   operator_inverted: !!a.invert,
                   operator_normalized: !!r.operator && op !== String(r.operator).trim() });
    return;
  }

  const v = a.onto ? lexValue(a.onto, r.value ?? r.quote) : String(r.value ?? r.quote ?? '');
  if (v === null) { unaligned.push({ source_key:key, quote:r.quote, reason:'valeur_categorielle_non_reconnue' }); return; }
  aligned.push({ ...base, op: Array.isArray(v) ? 'in' : '=', value:v, unit:'' });
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. Passage sur le portfolio (additif, jamais destructif)
// ─────────────────────────────────────────────────────────────────────────────
const inItem = $input.first().json;
if (inItem.pipeline_ready !== true) return [{ json: inItem }];

let p;
try { p = JSON.parse(String(inItem.output ?? '')); }
catch (e) { return [{ json: { ...inItem, alignment_error:'ALIGN_PARSE_ERROR: ' + e.message } }]; }

for (const f of (p.functionalities || [])) {
  const req = (f.requirements && typeof f.requirements === 'object' && !Array.isArray(f.requirements)) ? f.requirements : {};
  const fdesc = f.description || '';
  const aligned = [], unaligned = [];

  for (const [key, raw] of Object.entries(req)) {
    if (raw === null || raw === undefined || raw === '') continue;
    if (key === 'extra') {
      for (const x of (Array.isArray(raw) ? raw : [])) alignOne(x?.raw_key ?? 'extra', x, aligned, unaligned, fdesc);
    } else if (Array.isArray(raw)) {
      for (const v of raw) alignOne(key, (v && typeof v === 'object') ? v : { operator:'=', value:v, quote:String(v) }, aligned, unaligned, fdesc);
    } else {
      alignOne(key, raw, aligned, unaligned, fdesc);
    }
  }

  // Doublons : même attribut + même opérateur (+ même zone pour les zones).
  // Numérique : on garde la contrainte la PLUS STRICTE.
  const keep = new Map();
  for (const c of aligned) {
    const k = (c.attribute || c.gst) + '|' + c.op + (c.kind === 'zone' || c.kind === 'string' ? '|' + c.value : '');
    const prev = keep.get(k);
    if (!prev) { keep.set(k, c); continue; }
    if (typeof c.value === 'number' && typeof prev.value === 'number')
      prev.value = c.op.startsWith('>') ? Math.max(prev.value, c.value) : Math.min(prev.value, c.value);
  }

  f.requirements_aligned   = [...keep.values()];
  f.requirements_unaligned = unaligned;
  console.log(`[ALIGN] ${f.id}: ${f.requirements_aligned.length} alignée(s) ` +
              `(${f.requirements_aligned.filter(c=>c.in_ontology).length} vérifiable(s)), ` +
              `${unaligned.length} non alignée(s)`);
}

return [{ json: { ...inItem, output: JSON.stringify(p) } }];

let lang = 'fr';
try { lang = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}
const q=$json.clarification_question;
const e=$json.pipeline_error||(lang==='en'?'INVALID_PORTFOLIO':'PORTFOLIO_INVALIDE');
const fallback = lang === 'en'
  ? `The request could not be normalized without risking the loss of the existing state (${e}). Please clarify what needs to be added or changed.`
  : `La demande n'a pas pu être normalisée sans risque de perdre l'état existant (${e}). Précisez le besoin à ajouter ou modifier.`;
return [{json:{output:q?String(q):fallback}}];

// ===== Activation automatique de la Service Order TMF641 =====
// OpenSlice crée la commande en état INITIAL : tant qu'elle n'est pas ACKNOWLEDGED,
// l'orchestration ne démarre pas. Ce node fait le PATCH que l'on faisait à la main.
const BASE = 'http://openslice.example';                                   // même hôte que create_service_order
const ORDER_PATH = '/tmf-api/serviceOrdering/v4/serviceOrder';
const TARGET_STATE = 'ACKNOWLEDGED';
const PATCHABLE = ['INITIAL'];            // états depuis lesquels on active la commande
const MEM_TAG = 'N8N_STATE_V8::';

const prev = $input.first().json;
const passthrough = { ...prev };
const HTTP = (this && this.helpers && typeof this.helpers.httpRequest === 'function') ? this.helpers : null;
let lang = 'fr';
try { lang = $('Load Request State').first().json.lang || 'fr'; } catch (e) {}

// Commandes repérées par "Deployment Reply" (données réelles des outils, pas le texte du LLM)
const detail = Array.isArray(prev.orders_detail) ? prev.orders_detail : [];
const ids = [...new Set((detail.length ? detail.map(o => o.order_id) : (prev.orders_saved || [])).filter(Boolean))];
if (!ids.length || !HTTP) return [{ json: passthrough }];

let texte = String(prev.output ?? '');
const results = [];

try {
  const tok = await HTTP.httpRequest({
    method: 'POST',
    url: BASE + '/auth/realms/openslice/protocol/openid-connect/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=password&client_id=osapiWebClientId&username=__OPENSLICE_USERNAME__&password=__OPENSLICE_PASSWORD__',
    json: true
  });
  const H = { Authorization: 'Bearer ' + tok.access_token };

  const getState = async (id) => {
    const o = await HTTP.httpRequest({ method: 'GET', url: BASE + ORDER_PATH + '/' + id, headers: H, json: true });
    return String(o.state || '').toUpperCase();
  };

  for (const id of ids) {
    let before = null;
    try { before = await getState(id); } catch (e) { results.push({ id, ok: false, msg: (lang === 'en' ? 'read failed: ' : 'lecture impossible : ') + e.message }); continue; }

    if (!PATCHABLE.includes(before)) { results.push({ id, ok: true, state: before, skipped: true }); continue; }

    let last = '';
    for (const ct of ['application/merge-patch+json', 'application/json']) {
      try {
        const r = await HTTP.httpRequest({
          method: 'PATCH', url: BASE + ORDER_PATH + '/' + id,
          headers: { ...H, 'Content-Type': ct },
          body: JSON.stringify({ state: TARGET_STATE }),
          returnFullResponse: true
        });
        if (r.statusCode >= 200 && r.statusCode < 300) { last = ''; break; }
        last = 'HTTP ' + r.statusCode + ' (' + ct + ')';
      } catch (e) { last = e.message + ' (' + ct + ')'; }
    }

    let after = before;
    try { after = await getState(id); } catch (e) {}
    if (after === TARGET_STATE) results.push({ id, ok: true, state: after });
    else results.push({ id, ok: false, state: after, msg: last || (lang === 'en' ? 'state unchanged (' : 'état inchangé (') + after + ')' });
  }
} catch (e) {
  results.push({ id: ids[0], ok: false, msg: (lang === 'en' ? 'OpenSlice authentication failed: ' : 'authentification OpenSlice impossible : ') + e.message });
}

// --- Compte rendu dans le chat ---
const okIds = results.filter(r => r.ok).map(r => r.id);
const koIds = results.filter(r => !r.ok);
if (okIds.length) {
  texte = texte.replace(/((?:Statut|Status)\s*:\s*)INITIAL/gi, '$1' + TARGET_STATE);
  const done = results.filter(r => r.ok && !r.skipped);
  if (lang === 'en') {
    if (done.length) texte += `\n\nOrder status moved to ${TARGET_STATE}: OpenSlice deployment starts automatically.`;
    else texte += `\n\nThe order was already in state ${results.find(r => r.skipped)?.state || TARGET_STATE}, no change needed.`;
  } else {
    if (done.length) texte += `\n\nStatut de la commande passé à ${TARGET_STATE} : le déploiement OpenSlice démarre automatiquement.`;
    else texte += `\n\nLa commande était déjà à l'état ${results.find(r => r.skipped)?.state || TARGET_STATE}, aucun changement nécessaire.`;
  }
}
for (const r of koIds) {
  if (lang === 'en') {
    texte += `\n\n⚠️ Automatic activation failed for Order ${r.id} (${r.msg || r.state || 'unknown reason'}).`
          + `\nMove the order to ${TARGET_STATE} in OpenSlice to start the deployment.`;
  } else {
    texte += `\n\n⚠️ Activation automatique impossible pour l'Order ${r.id} (${r.msg || r.state || 'raison inconnue'}).`
          + `\nPassez la commande à ${TARGET_STATE} dans OpenSlice pour lancer le déploiement.`;
  }
}

// --- Report du nouvel état dans la mémoire ---
let memory_payload = prev.memory_payload ?? null;
try {
  const src = memory_payload || $('Load Request State').first().json.memory_payload_prev || null;
  if (src && src.startsWith(MEM_TAG)) {
    const rec = JSON.parse(src.slice(MEM_TAG.length));
    if (Array.isArray(rec.orders)) {
      const now = new Date().toISOString();
      for (const o of rec.orders) {
        const r = results.find(x => x.id === o.order_id);
        if (r && r.state) { o.state = r.state; o.acknowledged = r.state === TARGET_STATE; o.updated_at = now; }
      }
      rec.updated_at = now;
      memory_payload = MEM_TAG + JSON.stringify(rec);
    }
  }
} catch (e) { console.log('[ack] mémoire non mise à jour : ' + e.message); }

console.log('[ack] ' + JSON.stringify(results));
return [{ json: { ...passthrough, output: texte, memory_payload, acknowledged: okIds, ack_results: results } }];

// =============================================================================
// Node "Prepare Bundle Search"   (Code — Run Once for All Items)          v2
// Entrée : sortie true de "Enrichment Valid?" -> { output: <portfolio 2_bonnes_pratiques> }
// Règle unique : 2 capacités ou plus -> recherche d'un bundle par "Agent Bundle".
//                sinon               -> pas de bundle, Agent 3 par capacité comme avant.
// Sortie : { output, bundle_search_needed, bundle_covers_all:false, bundle_request }
// =============================================================================
const BUNDLE_MIN_CAPS = 2;

const raw = String($json.output ?? '').trim();
let o;
try { o = JSON.parse(raw); } catch (e) {
  return [{ json: { output: raw, bundle_search_needed: false, bundle_covers_all: false } }];
}
const funcs = Array.isArray(o.functionalities) ? o.functionalities : [];
const scope = funcs.map(f => f.id).sort();
o.bundle_scope = scope;
o.bundle_offer = null;
o.bundle_note = null;

if (funcs.length < BUNDLE_MIN_CAPS) {
  // une capacité qui portait l'offre bundle d'une révision précédente doit retrouver une offre individuelle
  for (const f of funcs) {
    f.idempotence = f.idempotence || {};
    f.idempotence.bundle_status = 'not_covered';
    if (f.candidate_offers?.[0]?.is_bundle) {
      f.candidate_offers = [];
      f.idempotence.offer_status = 'unknown';
      f.idempotence.offer_rediscovery = true;
    }
  }
  o.bundle_status = 'not_applicable';
  console.log(`[bundle] not_applicable — ${funcs.length} capacité(s)`);
  return [{ json: { output: JSON.stringify(o), bundle_search_needed: false, bundle_covers_all: false, bundle_request: null } }];
}

const quotes = r => Object.entries(r || {}).flatMap(([k, v]) =>
  k === 'extra' ? (Array.isArray(v) ? v : []).map(e => e?.quote).filter(Boolean)
  : k === 'regions' && Array.isArray(v) ? ['regions: ' + v.join(', ')]
  : (v && typeof v === 'object' && v.quote ? [String(v.quote)] : []));
const capabilities = funcs.map(f => ({
  id: f.id,
  categorie: f.categorie || 'metier',
  business_capability_name: f.business_capability_name || null,
  sous_type_5g: f.sous_type_5g || null,
  technical_capability_names: f.technical_capability_names || [],
  generic_service: f.matched_generic_service?.name || null,
  supports: f.supports || [],
  requirements: quotes(f.requirements),
}));
const searchQuery = [...new Set([
  ...funcs.map(f => f.matched_generic_service?.name),
  ...funcs.map(f => f.sous_type_5g),
  ...funcs.map(f => f.business_capability_name),
  'bundle',
].filter(Boolean))].join(' ');

o.bundle_status = 'searching';
console.log(`[bundle] recherche pour ${scope.join(',')}`);
return [{ json: { output: JSON.stringify(o), bundle_search_needed: true, bundle_covers_all: false, bundle_request: { scope, capabilities, query: searchQuery } } }];

