parameters.jsCode:
// === get_bundle_composition — lecture TMF633 d'une spec bundle et de ses CFS membres ===
// Arguments de l'agent = variable `query` (pas $input).
let params = {};
try {
  const q = (typeof query !== 'undefined') ? query : null;
  if (q && typeof q === 'object') params = q;
  else if (typeof q === 'string' && q.trim()) { const s = q.trim(); try { params = JSON.parse(s); } catch (e) { params = { spec_id: s }; } }
} catch (e) { params = {}; }
if (typeof params !== 'object' || params === null) params = {};

let key = String(params.spec_id || params.spec_name || params.name || '').trim().replace(/^["'\s]+|["'\s]+$/g, '');
if (!key) return 'ARRET_OUTIL: aucun spec_id de bundle fourni. Ne rappelle PAS cet outil sans spec_id.';

const BASE = 'http://openslice.example';
const SPEC = '/tmf-api/serviceCatalogManagement/v4/serviceSpecification';
const MAX_MEMBERS = 10;

let H;
try {
  const tk = await this.helpers.httpRequest({
    method: 'POST',
    url: BASE + '/auth/realms/openslice/protocol/openid-connect/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=password&client_id=osapiWebClientId&username=__OPENSLICE_USERNAME__&password=__OPENSLICE_PASSWORD__',
    json: true,
  });
  H = { 'Authorization': 'Bearer ' + tk.access_token };
} catch (e) { return 'ARRET_OUTIL: authentification OpenSlice impossible : ' + e.message; }

const isUuid = s => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
const getSpec = async id => this.helpers.httpRequest({ method: 'GET', url: BASE + SPEC + '/' + encodeURIComponent(id), headers: H, json: true });

let spec;
try {
  if (isUuid(key)) spec = await getSpec(key);
  else {
    const list = await this.helpers.httpRequest({ method: 'GET', url: BASE + SPEC, headers: H, qs: { limit: 100 }, json: true });
    const hit = (list || []).find(s => (s.name || '').toLowerCase() === key.toLowerCase())
             || (list || []).find(s => (s.name || '').toLowerCase().includes(key.toLowerCase()));
    if (hit && hit.id) spec = await getSpec(hit.id);
  }
} catch (e) { return 'ARRET_OUTIL: lecture TMF633 impossible pour "' + key + '" : ' + e.message; }
if (!spec || !spec.id) return 'ARRET_OUTIL: aucune ServiceSpecification trouvee pour "' + key + '". Ne rappelle PAS cet outil avec cette valeur.';

// Membres du bundle = serviceSpecRelationship (hors relations de réalisation vers des RFS)
const rels = Array.isArray(spec.serviceSpecRelationship) ? spec.serviceSpecRelationship : [];
let memberRels = rels.filter(r => r && r.id && !/realiz/i.test(String(r.relationshipType || '')));
if (!memberRels.length) memberRels = rels.filter(r => r && r.id);

const members = [];
for (const rel of memberRels.slice(0, MAX_MEMBERS)) {
  try {
    const m = await getSpec(rel.id);
    members.push({
      spec_id: String(m.id || rel.id), spec_name: m.name || rel.name || null,
      relationship_type: rel.relationshipType || null,
      type: m['@type'] || m.type || null, is_bundle: m.isBundle === true,
      category: m.category || null, lifecycle_status: m.lifecycleStatus || null,
      description: String(m.description || '').replace(/\s+/g, ' ').slice(0, 200),
    });
  } catch (e) {
    members.push({ spec_id: String(rel.id), spec_name: rel.name || null, relationship_type: rel.relationshipType || null, error: e.message });
  }
}

const isBundle = spec.isBundle === true ? true : (spec.isBundle === false ? false : null);
const comp = { spec_id: String(spec.id), name: spec.name || null, is_bundle: isBundle, lifecycle_status: spec.lifecycleStatus || null, members };

let out = 'BUNDLE: ' + (spec.name || '') + '\nspec_id: ' + spec.id + '\nisBundle: ' + (isBundle === null ? 'unknown' : isBundle) + '\n';
out += 'MEMBER CFS (serviceSpecRelationship):\n';
out += members.length
  ? members.map(m => '  - member_spec_id=' + m.spec_id + ' | name=' + (m.spec_name || 'N/A') + ' | relationshipType=' + (m.relationship_type || 'N/A')
      + (m.category ? ' | category=' + m.category : '') + (m.description ? ' | description=' + m.description : '') + (m.error ? ' | error=' + m.error : '')).join('\n')
  : '  (aucun membre)';
out += '\nBUNDLE_COMPOSITION_JSON: ' + JSON.stringify(comp);
return out;

