parameters.jsCode:
// =============================================================================
// Node "Assemble Bundle Discovery"   (Code — Run Once for All Items)             v1
// L'agent propose UN bundle et l'affectation capacité -> CFS membre.
// Ce nœud valide de façon déterministe contre les retours RÉELS des outils :
//   - la composition du bundle a bien été lue par get_bundle_composition (TMF633)
//   - la spec est un bundle (isBundle)
//   - CHAQUE capacité est affectée à UN CFS membre existant, sans doublon
// Couverture partielle => bundle rejeté, retour au chemin Agent 3 par capacité.
// =============================================================================
const ACCEPT_UNFLAGGED_BUNDLE = false; // true = accepter une spec isBundle=false si elle a >= 2 CFS membres

function clean(s){return String(s??'').replace(/<think>[\s\S]*?<\/think>/gi,'').replace(/<\/?think>/gi,'').replace(/```(?:json)?/gi,'').trim();}
function clone(v){return v===undefined?undefined:JSON.parse(JSON.stringify(v));}
function tryParse(s){const t=clean(s);if(!t)return null;try{const v=JSON.parse(t);return v&&typeof v==='object'?v:null;}catch(_){}const st=t.indexOf('{');if(st<0)return null;let d=0,q=false,e=false;for(let i=st;i<t.length;i++){const c=t[i];if(q){if(e)e=false;else if(c==='\\')e=true;else if(c==='"')q=false;continue;}if(c==='"')q=true;else if(c==='{')d++;else if(c==='}'&&--d===0){try{return JSON.parse(t.slice(st,i+1));}catch(_){return null;}}}return null;}
function deepParse(v,n=0){if(n>40)return v;if(typeof v==='string'){const t=v.trim();if(/^[\[{"]/.test(t)){try{return deepParse(JSON.parse(t),n+1);}catch(_){}}return v;}if(Array.isArray(v))return v.map(x=>deepParse(x,n+1));if(v&&typeof v==='object'){const o={};for(const[k,x]of Object.entries(v))o[k]=deepParse(x,n+1);return o;}return v;}
function steps(it){return Array.isArray(it.json.intermediateSteps)?it.json.intermediateSteps:[];}
function obsTexts(it){return steps(it).map(s=>{const o=s&&s.observation;let t=typeof o==='string'?o:JSON.stringify(o??'');try{const p=JSON.parse(t);if(typeof p==='string')t=p;}catch(_){}return t;});}
function collectDocs(it){const docs=[];for(const s of steps(it)){const walk=v=>{if(Array.isArray(v)){v.forEach(walk);return;}if(v&&typeof v==='object'){if(v.metadata&&typeof v.metadata==='object')docs.push({pageContent:String(v.pageContent??''),metadata:v.metadata});else Object.values(v).forEach(walk);}};walk(deepParse(s&&s.observation));}return docs;}
function toolFailed(it){return obsTexts(it).some(t=>/ARRET_OUTIL|error|erreur|exception|ECONNREFUSED|timeout/i.test(t)&&!/metadata|BUNDLE_COMPOSITION_JSON/i.test(t));}
function num(v){const x=Number(v);return v!==null&&v!==''&&Number.isFinite(x)?x:null;}
function mget(m,keys){const ks=Object.keys(m||{});for(const k of keys){const h=ks.find(x=>x.toLowerCase().replace(/[\s_-]/g,'')===k);if(h&&m[h]!=null&&m[h]!=='')return m[h];}return null;}

const prep = $('Prepare Bundle Search').first().json;
const o = JSON.parse(prep.output);
const funcs = o.functionalities;
const scope = funcs.map(f => f.id).sort();
const it = $input.first();
const a = tryParse(it.json.output);

// compositions réellement lues (TMF633 serviceSpecRelationship)
const comps = [];
for (const t of obsTexts(it)) {
  const s = String(t).replace(/\\n/g, '\n');
  const i = s.indexOf('BUNDLE_COMPOSITION_JSON:');
  if (i < 0) continue;
  const c = tryParse(s.slice(i + 'BUNDLE_COMPOSITION_JSON:'.length));
  if (c && c.spec_id) comps.push(c);
}
// score RAG du bundle (si présent dans les métadonnées)
const ragScore = id => { for (const d of collectDocs(it)) { const m = d.metadata; const sid = mget(m, ['specid','servicespecid','uuid','id']) ?? (/spec_id\s*[:=]\s*([0-9a-f-]{36})/i.exec(d.pageContent) || [])[1]; if (String(sid) === String(id)) return num(mget(m, ['score'])); } return null; };

function unbundle() {
  for (const f of funcs) {
    f.idempotence = f.idempotence || {};
    f.idempotence.bundle_status = 'not_covered';
    const of = Array.isArray(f.candidate_offers) ? f.candidate_offers[0] : null;
    if (of && of.is_bundle) { f.candidate_offers = []; f.idempotence.offer_status = 'unknown'; f.idempotence.offer_rediscovery = true; }
  }
}

let status = null, note = null, offer = null;
const proposed = a && a.bundle_spec_id ? String(a.bundle_spec_id).trim() : null;

if (proposed) {
  const comp = comps.find(c => String(c.spec_id) === proposed);
  if (!comp) { status = 'rejected'; note = `composition du bundle ${proposed} non lue (get_bundle_composition non appelé ou en erreur)`; }
  else if (comp.is_bundle === false && !(ACCEPT_UNFLAGGED_BUNDLE && (comp.members || []).length >= 2)) { status = 'rejected'; note = `${comp.name || proposed} n'est pas un bundle (isBundle=false dans TMF633)`; }
  else if (!(comp.members || []).length) { status = 'rejected'; note = `${comp.name || proposed} : aucun CFS membre dans serviceSpecRelationship`; }
  else {
    const cov = new Map();
    const list = Array.isArray(a.coverage) ? a.coverage
      : (a.coverage && typeof a.coverage === 'object' ? Object.entries(a.coverage).map(([k, v]) => ({ functionality_id: k, member_spec_id: v })) : []);
    for (const c of list) if (c && c.functionality_id && c.member_spec_id) cov.set(String(c.functionality_id), String(c.member_spec_id).trim());
    const members = new Map(comp.members.map(m => [String(m.spec_id), m]));
    const missing = [], unknown = [], used = new Map(), dup = [];
    for (const f of funcs) {
      const mid = cov.get(f.id);
      if (!mid) { missing.push(f.id); continue; }
      if (!members.has(mid)) { unknown.push(`${f.id}->${mid}`); continue; }
      if (used.has(mid)) { dup.push(`${used.get(mid)}/${f.id}`); continue; }
      used.set(mid, f.id);
    }
    if (missing.length) { status = 'rejected'; note = `couverture partielle : ${missing.join(', ')} non couverte(s) par ${comp.name || proposed}`; }
    else if (unknown.length) { status = 'rejected'; note = `CFS membre inconnu dans la composition : ${unknown.join(', ')}`; }
    else if (dup.length) { status = 'rejected'; note = `même CFS membre affecté à plusieurs capacités : ${dup.join(', ')}`; }
    else {
      status = 'new_match';
      offer = {
        spec_id: String(comp.spec_id),
        spec_name: comp.name || a.bundle_spec_name || null,
        score: num(a.score) ?? ragScore(comp.spec_id),
        is_bundle: true,
        lifecycle_status: comp.lifecycle_status ?? null,
        members: comp.members.map(m => ({
          spec_id: String(m.spec_id), spec_name: m.spec_name || null,
          relationship_type: m.relationship_type || null,
          covers: funcs.filter(f => cov.get(f.id) === String(m.spec_id)).map(f => f.id),
        })),
        covered_functionalities: scope,
        source: 'RAG_Bundle_Offerings + TMF633 serviceSpecRelationship',
      };
    }
  }
} else if (a && ['not_found', 'tool_error'].includes(String(a.bundle_status))) {
  status = String(a.bundle_status); note = a.reason ? String(a.reason).slice(0, 300) : null;
} else if (!steps(it).length) {
  status = 'tool_error'; note = 'agent bundle : aucun outil appelé et sortie vide';
} else {
  status = toolFailed(it) ? 'tool_error' : 'not_found'; note = 'agent bundle : sortie vide ou illisible';
}

if (offer) {
  for (const f of funcs) {
    const m = offer.members.find(x => x.covers.includes(f.id));
    f.candidate_offers = [{
      spec_id: offer.spec_id, spec_name: offer.spec_name, score: offer.score,
      committed_sla: null, realized_by_rfs: [],
      is_bundle: true, bundle_member: { spec_id: m.spec_id, spec_name: m.spec_name },
    }];
    f.idempotence = f.idempotence || {};
    f.idempotence.offer_status = 'new_match';
    f.idempotence.bundle_status = 'covered';
    delete f.idempotence.offer_rediscovery;
    if (Object.prototype.hasOwnProperty.call(f, 'offer_status')) delete f.offer_status;
  }
  o.etape = '3_catalogue';
} else {
  unbundle();
}
o.bundle_status = status;
o.bundle_offer = offer;
o.bundle_scope = scope;
o.bundle_note = note;
console.log(`[bundle] ${status}${offer ? ' : ' + offer.spec_name + ' (' + offer.spec_id + ')' : ''}${note ? ' — ' + note : ''}`);
return [{ json: { output: JSON.stringify(o), bundle_search_needed: false, bundle_covers_all: !!offer } }];
